"use client"

import * as React from "react"
import { Accordion as AccordionPrimitive } from "radix-ui"

import { Icon } from "@/components/ui/icon"
import { useInk, useMergedRef } from "@/lib/ink/react"
import { accordionRuleRecipe, accordionTriggerRecipe } from "@/lib/ink/recipes/accordion-ink"
import { MARGIN_BRACKET_DRAW, marginBracketRecipe, type MarginBracketParams } from "@/lib/ink/recipes/margin-bracket-ink"
import { markTouched } from "@/lib/ink/recipes/draw-on-ink"
import { cn } from "@/lib/utils"

type BracketKind = MarginBracketParams["kind"] | false
const BracketContext = React.createContext<BracketKind>("curly")

const FOLD = `@keyframes ll-accordion-down { from { height: 0; clip-path: inset(0); } to { height: var(--radix-accordion-content-height); clip-path: inset(0); } }
@keyframes ll-accordion-up { from { height: var(--radix-accordion-content-height); clip-path: inset(0); } to { height: 0; clip-path: inset(0); } }`

const SWIPE = "hover:[&>svg_[data-part=swipe]]:animate-[ll-wipe_var(--ll-dur-sheet)_var(--ll-ease-out)_both]"

function Rule() {
  const { hostRef, hostProps, node } = useInk({ recipe: accordionRuleRecipe, params: {}, kind: "rule", still: true })
  return (
    <span
      data-slot="accordion-rule"
      aria-hidden="true"
      ref={hostRef}
      {...(node ? hostProps : {})}
      className="pointer-events-none absolute inset-x-0 bottom-0 block h-2 forced-colors:hidden"
    >
      {node}
    </span>
  )
}

function Bracket({ kind }: { kind: Exclude<BracketKind, false> }) {
  const { hostRef, hostProps, node } = useInk({ recipe: marginBracketRecipe, params: { kind }, kind: "bracket", still: true })
  return (
    <span
      data-slot="accordion-bracket"
      aria-hidden="true"
      ref={hostRef}
      {...(node ? hostProps : {})}
      className={cn("pointer-events-none absolute inset-y-0 start-0 block w-3.5 forced-colors:hidden", MARGIN_BRACKET_DRAW)}
    >
      {node}
    </span>
  )
}

function Accordion({
  bracket = "curly",
  onClickCapture,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Root> & {
  bracket?: BracketKind
}) {
  return (
    <BracketContext.Provider value={bracket}>
      <style href="ll-accordion" precedence="low">
        {FOLD}
      </style>
      <AccordionPrimitive.Root
        data-slot="accordion"
        onClickCapture={(e) => {
          markTouched(e)
          onClickCapture?.(e)
        }}
        {...props}
      />
    </BracketContext.Provider>
  )
}

function AccordionItem({ className, children, ...props }: React.ComponentProps<typeof AccordionPrimitive.Item>) {
  return (
    <AccordionPrimitive.Item
      data-slot="accordion-item"
      className={cn("group/accordion-item relative pb-2 last:[&>[data-slot=accordion-rule]]:hidden", className)}
      {...props}
    >
      {children}
      <Rule />
    </AccordionPrimitive.Item>
  )
}

function AccordionTrigger({
  className,
  children,
  seed,
  ref,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Trigger> & {
  seed?: string | number
}) {
  const { hostRef, hostProps, node } = useInk({ recipe: accordionTriggerRecipe, params: { disabled: !!props.disabled }, kind: "row", seed, still: true })
  return (
    <AccordionPrimitive.Header className="flex">
      <AccordionPrimitive.Trigger
        data-slot="accordion-trigger"
        ref={useMergedRef<HTMLButtonElement>(hostRef, ref)}
        {...hostProps}
        className={cn(
          "group/accordion-trigger relative isolate -mx-2 flex flex-1 items-start justify-between gap-4 px-2 py-3.5 text-start font-hand text-base font-bold transition-[color] disabled:pointer-events-none disabled:text-pencil-text compact:py-2.5 calm:py-2 calm:text-[15px]",
          "[&_svg:not(.absolute):not([class*='size-'])]:size-4 [&[data-state=open]>[data-chevron]]:rotate-180",
          SWIPE,
          className
        )}
        {...props}
      >
        {node}
        {children}
        <Icon name="chevron-down" data-chevron="" size={16} className="pointer-events-none mt-1 shrink-0 transition-transform duration-(--ll-dur-sheet) ease-settle" />
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  )
}

const OUTER_PADDING = /^(?:[^\s:]+:)*!?-?(?:p|py|pt|pb)-/

function splitContentClass(className?: string) {
  const outer: string[] = []
  const inner: string[] = []
  for (const token of (className ?? "").split(/\s+/)) {
    if (!token) continue
    ;(OUTER_PADDING.test(token) ? outer : inner).push(token)
  }
  return { outer: outer.join(" "), inner: inner.join(" ") }
}

function AccordionContent({ className, children, ...props }: React.ComponentProps<typeof AccordionPrimitive.Content>) {
  const bracket = React.useContext(BracketContext)
  const split = splitContentClass(className)
  return (
    <AccordionPrimitive.Content
      data-slot="accordion-content"
      className="group/accordion-content text-sm data-[state=closed]:animate-[ll-accordion-up_var(--ll-dur-sheet)_var(--ll-ease-out)] data-[state=open]:animate-[ll-accordion-down_var(--ll-dur-sheet)_var(--ll-ease-out)]"
      {...props}
    >
      <div className={cn("pt-0 pb-4", split.outer)}>
        <div className={cn("relative in-data-touched:group-data-[state=open]/accordion-content:animate-soak", bracket && "ps-5", split.inner)}>
          {bracket ? <Bracket kind={bracket} /> : null}
          {children}
        </div>
      </div>
    </AccordionPrimitive.Content>
  )
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent }

"use client"

import * as React from "react"
import { AlertDialog as AlertDialogPrimitive } from "radix-ui"

import { Button } from "@/components/ui/button"
import { Paper, type PaperProps } from "@/components/ui/paper"
import { Tape } from "@/components/ui/tape"
import { useInk, useInkScope, useInkSeed, useMergedRef } from "@/lib/ink/react"
import { alertMediaRecipe, type AlertMediaTone } from "@/lib/ink/recipes/alert-dialog-ink"
import { cn } from "@/lib/utils"

function AlertDialog({ ...props }: React.ComponentProps<typeof AlertDialogPrimitive.Root>) {
  return <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />
}

function AlertDialogTrigger({ ...props }: React.ComponentProps<typeof AlertDialogPrimitive.Trigger>) {
  return <AlertDialogPrimitive.Trigger data-slot="alert-dialog-trigger" {...props} />
}

function AlertDialogPortal({ ...props }: React.ComponentProps<typeof AlertDialogPrimitive.Portal>) {
  return <AlertDialogPrimitive.Portal data-slot="alert-dialog-portal" {...props} />
}

function AlertDialogOverlay({ className, ...props }: React.ComponentProps<typeof AlertDialogPrimitive.Overlay>) {
  const scope = useInkScope()
  return (
    <AlertDialogPrimitive.Overlay
      data-slot="alert-dialog-overlay"
      {...scope}
      className={cn(
        "fixed inset-0 z-(--ll-z-overlay) flex overflow-y-auto overscroll-contain p-4 [background:var(--ll-overlay-dim)] [scrollbar-gutter:stable_both-edges] max-sm:p-0",
        "duration-(--ll-dur-sheet) data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:animate-in data-[state=open]:fade-in-0",
        className
      )}
      {...props}
    />
  )
}

function AlertDialogContent({
  className,
  size = "default",
  tone = "default",
  children,
  stock = "paper",
  edge,
  tilt,
  seed: seedProp,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Content> &
  Pick<PaperProps, "stock" | "edge" | "tilt" | "seed"> & {
    size?: "default" | "sm"
    tone?: "default" | "danger"
  }) {
  const scope = useInkScope()
  const seed = useInkSeed(seedProp)
  return (
    <AlertDialogPortal>
      <AlertDialogOverlay>
        <AlertDialogPrimitive.Content asChild {...props}>
          <Paper
            data-slot="alert-dialog-content"
            data-size={size}
            data-tone={tone}
            stock={stock}
            edge={edge}
            tilt={tilt}
            rules="none"
            seed={seed}
            {...scope}
            className={cn(
              "group/alert-dialog-content m-auto grid w-full max-w-lg gap-4 p-6 text-foreground outline-hidden compact:p-5 calm:p-4 data-[size=sm]:max-w-xs",
              "max-sm:mb-0 max-sm:max-w-none max-sm:pb-[max(1.5rem,env(safe-area-inset-bottom))] max-sm:compact:pb-[max(1.25rem,env(safe-area-inset-bottom))] max-sm:calm:pb-[max(1rem,env(safe-area-inset-bottom))] max-sm:[--ll-tilt:0deg]!",
              "data-[state=open]:animate-sheet-drop max-sm:data-[state=open]:animate-in max-sm:data-[state=open]:slide-in-from-bottom-16 max-sm:data-[state=open]:fade-in-0",
              "duration-(--ll-dur-fade) data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 max-sm:data-[state=closed]:slide-out-to-bottom-8",
              className
            )}
          >
            {tone === "danger" && (
              <>
                <Tape kind="washi-stripes" color="tomato" length={68} height={20} angle={-38} seed={`${seed}:hz-a`} className="absolute -top-2 -left-7 z-(--ll-z-prop) max-sm:hidden calm:hidden" />
                <Tape kind="washi-stripes" color="tomato" length={68} height={20} angle={36} seed={`${seed}:hz-b`} className="absolute -top-2 -right-7 z-(--ll-z-prop) max-sm:hidden calm:hidden" />
              </>
            )}
            {children}
          </Paper>
        </AlertDialogPrimitive.Content>
      </AlertDialogOverlay>
    </AlertDialogPortal>
  )
}

function AlertDialogHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-header"
      className={cn(
        "grid grid-rows-[auto_1fr] place-items-center gap-1.5 text-center has-data-[slot=alert-dialog-media]:grid-rows-[auto_auto_1fr] has-data-[slot=alert-dialog-media]:gap-x-6 sm:group-data-[size=default]/alert-dialog-content:place-items-start sm:group-data-[size=default]/alert-dialog-content:text-start sm:group-data-[size=default]/alert-dialog-content:has-data-[slot=alert-dialog-media]:grid-rows-[auto_1fr]",
        className
      )}
      {...props}
    />
  )
}

function AlertDialogFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-footer"
      className={cn(
        "flex flex-col-reverse gap-2 group-data-[size=sm]/alert-dialog-content:grid group-data-[size=sm]/alert-dialog-content:grid-cols-2 sm:flex-row sm:justify-end",
        className
      )}
      {...props}
    />
  )
}

function AlertDialogTitle({ className, ...props }: React.ComponentProps<typeof AlertDialogPrimitive.Title>) {
  return (
    <AlertDialogPrimitive.Title
      data-slot="alert-dialog-title"
      className={cn(
        "font-script text-[1.7rem] leading-none font-semibold sm:group-data-[size=default]/alert-dialog-content:group-has-data-[slot=alert-dialog-media]/alert-dialog-content:col-start-2",
        className
      )}
      {...props}
    />
  )
}

function AlertDialogDescription({ className, ...props }: React.ComponentProps<typeof AlertDialogPrimitive.Description>) {
  return <AlertDialogPrimitive.Description data-slot="alert-dialog-description" className={cn("text-sm text-muted-foreground", className)} {...props} />
}

function AlertDialogMedia({
  className,
  tone = "default",
  seed: seedProp,
  children,
  ref,
  ...props
}: React.ComponentProps<"div"> & {
  tone?: AlertMediaTone
  seed?: string | number
}) {
  const seed = useInkSeed(seedProp)
  const { hostRef, hostProps, node } = useInk({ recipe: alertMediaRecipe, params: { tone }, kind: "plate", size: [64, 64], seed })
  return (
    <div
      data-slot="alert-dialog-media"
      ref={useMergedRef<HTMLElement>(hostRef, ref as React.Ref<HTMLElement> | undefined)}
      {...hostProps}
      className={cn(
        "relative isolate mb-2 inline-flex size-16 items-center justify-center sm:group-data-[size=default]/alert-dialog-content:row-span-2 *:[svg:not(.absolute):not([class*='size-'])]:size-8",
        className
      )}
      {...props}
    >
      {node}
      {children}
    </div>
  )
}

function AlertDialogAction({
  className,
  variant = "default",
  size = "default",
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Action> & Pick<React.ComponentProps<typeof Button>, "variant" | "size">) {
  return (
    <Button variant={variant} size={size} asChild>
      <AlertDialogPrimitive.Action data-slot="alert-dialog-action" className={cn(className)} {...props} />
    </Button>
  )
}

function AlertDialogCancel({
  className,
  variant = "outline",
  size = "default",
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Cancel> & Pick<React.ComponentProps<typeof Button>, "variant" | "size">) {
  return (
    <Button variant={variant} size={size} asChild>
      <AlertDialogPrimitive.Cancel data-slot="alert-dialog-cancel" className={cn(className)} {...props} />
    </Button>
  )
}

export {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogOverlay,
  AlertDialogPortal,
  AlertDialogTitle,
  AlertDialogTrigger,
}

"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { Paper } from "@/components/ui/paper"
import { useInk, useMergedRef } from "@/lib/ink/react"
import { alertRecipe, type AlertTone } from "@/lib/ink/recipes/alert-ink"
import { cn } from "@/lib/utils"

const alertVariants = cva(
  "relative isolate grid w-full grid-cols-[0_1fr] items-start gap-y-0.5 px-4 py-3 text-sm compact:py-2.5 calm:px-3 calm:py-2 has-[>svg:not(.absolute)]:grid-cols-[calc(var(--spacing)*4)_1fr] has-[>svg:not(.absolute)]:gap-x-3 [&>svg:not(.absolute)]:size-4 [&>svg:not(.absolute)]:translate-y-0.5 [&>svg:not(.absolute)]:text-current [&:not(:has(>svg:not(.absolute)))>svg_[data-part=icon-mark]]:hidden",
  {
    variants: {
      variant: {
        default: "text-card-foreground",
        destructive: "text-destructive *:data-[slot=alert-description]:text-destructive [&>svg:not(.absolute)]:text-current",
        info: "text-card-foreground [&>svg:not(.absolute)]:text-ink-you",
        success: "text-card-foreground [&>svg:not(.absolute)]:text-green",
        warning: "text-card-foreground",
        note: "px-5 py-4 text-ink *:data-[slot=alert-description]:text-ink-soft",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

function Alert({
  className,
  variant,
  seed,
  ref,
  children,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof alertVariants> & {
    seed?: string | number
  }) {
  const tone: AlertTone = variant ?? "default"
  const { hostRef, hostProps, node } = useInk({ recipe: alertRecipe, params: { tone }, kind: "alert", seed, still: true })
  const merged = useMergedRef<HTMLDivElement>(hostRef, ref)

  if (tone === "note") {
    return (
      <Paper
        data-slot="alert"
        role="alert"
        stock="sticky-yellow"
        tape="corner"
        seed={seed}
        ref={ref as React.Ref<HTMLElement> | undefined}
        className={cn(alertVariants({ variant }), className)}
        {...props}
      >
        {children}
      </Paper>
    )
  }

  return (
    <div
      data-slot="alert"
      data-variant={tone}
      role="alert"
      ref={merged}
      {...hostProps}
      className={cn(alertVariants({ variant }), className)}
      {...props}
    >
      {node}
      {children}
    </div>
  )
}

function AlertTitle({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="alert-title" className={cn("col-start-2 line-clamp-1 min-h-4 font-bold", className)} {...props} />
}

function AlertDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-description"
      className={cn("col-start-2 grid justify-items-start gap-1 text-sm text-muted-foreground [&_p]:leading-relaxed", className)}
      {...props}
    />
  )
}

export { Alert, AlertTitle, AlertDescription }

"use client"

import * as React from "react"

import { MARK_REVEAL, useMarkPhase } from "@/hooks/use-mark-ink"
import { useInk, useMergedRef } from "@/lib/ink/react"
import { arrowRecipe, type ArrowCurve, type ArrowDirection, type ArrowHead } from "@/lib/ink/recipes/arrow-ink"
import type { MarkPen, MarkWeight } from "@/lib/ink/recipes/text-marks-ink"
import { cn } from "@/lib/utils"

type Target = React.RefObject<Element | null> | Element | string | null | undefined

const LABEL_SIDE: Record<ArrowDirection, string> = {
  right: "end-full top-1/2 me-2 -translate-y-1/2",
  left: "start-full top-1/2 ms-2 -translate-y-1/2",
  up: "top-full left-1/2 mt-1 -translate-x-1/2",
  down: "bottom-full left-1/2 mb-1 -translate-x-1/2",
  "up-right": "end-full bottom-0 me-2",
  "up-left": "start-full bottom-0 ms-2",
  "down-right": "end-full top-0 me-2",
  "down-left": "start-full top-0 ms-2",
}

function resolveTarget(t: Target): Element | null {
  if (!t) return null
  if (typeof t === "string") return document.querySelector(t)
  if (t instanceof Element) return t
  return t.current
}

function vectorTo(host: Element, target: Element, gap: number): { dx: number; dy: number } | null {
  const a = host.getBoundingClientRect()
  const b = target.getBoundingClientRect()
  const cx = a.left + a.width / 2, cy = a.top + a.height / 2
  const vx = b.left + b.width / 2 - cx, vy = b.top + b.height / 2 - cy
  const len = Math.hypot(vx, vy)
  if (len < 1) return null
  const enter = (lo: number, hi: number, o: number, v: number) => (v === 0 ? (o >= lo && o <= hi ? -Infinity : Infinity) : Math.min((lo - o) / v, (hi - o) / v))
  const t = Math.max(enter(b.left, b.right, cx, vx), enter(b.top, b.bottom, cy, vy))
  if (!(t >= 0 && t <= 1)) return null
  const reach = Math.max(0, len * t - gap)
  return { dx: Math.round(((vx / len) * reach) / 2) * 2, dy: Math.round(((vy / len) * reach) / 2) * 2 }
}

function Arrow({
  direction = "right",
  curve = "straight",
  head = "v",
  tone = "ink",
  weight = "regular",
  bend = "up",
  mirror = true,
  pointAt,
  gap = 6,
  animate = false,
  show = true,
  delay,
  seed,
  className,
  style,
  children,
  ref,
  ...props
}: React.ComponentProps<"span"> & {
  direction?: ArrowDirection
  curve?: ArrowCurve
  head?: ArrowHead
  tone?: MarkPen
  weight?: MarkWeight
  bend?: "up" | "down"
  mirror?: boolean
  pointAt?: Target
  gap?: number
  animate?: boolean
  show?: boolean
  delay?: number
  seed?: string | number
}) {
  const [host, setHost] = React.useState<HTMLElement | null>(null)
  const [vec, setVec] = React.useState<{ dx: number; dy: number } | null>(null)
  const aimed = pointAt !== undefined && pointAt !== null

  React.useLayoutEffect(() => {
    if (!aimed || !host) return
    const update = () => {
      const t = resolveTarget(pointAt)
      const v = t ? vectorTo(host, t, gap) : null
      setVec((prev) => (prev && v && prev.dx === v.dx && prev.dy === v.dy ? prev : v))
    }
    update()
    const stops: Array<() => void> = []
    if (typeof ResizeObserver !== "undefined") {
      const ro = new ResizeObserver(update)
      ro.observe(host)
      const t = resolveTarget(pointAt)
      if (t) ro.observe(t)
      ro.observe(document.documentElement)
      stops.push(() => ro.disconnect())
    }
    window.addEventListener("resize", update)
    stops.push(() => window.removeEventListener("resize", update))
    void document.fonts?.ready?.then(update)
    return () => stops.forEach((s) => s())
  }, [aimed, host, pointAt, gap])

  const params = { direction, curve, head, tone, weight, bend, mirror, animate, ...(aimed && vec ? { dx: vec.dx, dy: vec.dy } : {}) }
  const { hostRef, hostProps, node } = useInk({ recipe: arrowRecipe, params, kind: "arrow", seed })
  const { phaseRef, phaseProps } = useMarkPhase({ animate, show })
  const ready = !!node && show && !(aimed && !vec)
  return (
    <span
      data-slot="arrow"
      data-direction={aimed ? undefined : direction}
      ref={useMergedRef<HTMLElement>(hostRef, phaseRef, ref as React.Ref<HTMLElement> | undefined, setHost)}
      {...(ready ? hostProps : {})}
      {...phaseProps}
      style={{ ...(animate ? ({ "--ll-draw-delay": `${delay ?? 0}ms` } as React.CSSProperties) : undefined), ...style }}
      className={cn("relative isolate inline-block shrink-0 align-middle outline-none", aimed ? "size-6" : "h-10 w-20", animate && MARK_REVEAL, className)}
      {...props}
    >
      {ready ? node : null}
      {children ? (
        <span
          data-slot="arrow-label"
          className={cn("absolute font-script text-xl leading-none whitespace-nowrap text-ink-you", !aimed && LABEL_SIDE[direction], aimed && "start-full top-1/2 ms-2 -translate-y-1/2")}
        >
          {children}
        </span>
      ) : null}
    </span>
  )
}

export { Arrow }

"use client"

import { AspectRatio as AspectRatioPrimitive } from "radix-ui"

function AspectRatio({ ...props }: React.ComponentProps<typeof AspectRatioPrimitive.Root>) {
  return <AspectRatioPrimitive.Root data-slot="aspect-ratio" {...props} />
}

export { AspectRatio }

"use client"

import * as React from "react"

import type { ArtDef } from "@/lib/ink/art/types"
import { drawSkeleton, memo } from "@/lib/ink/art-draw"
import { useEnsureInkDefs, useInkSeed } from "@/lib/ink/react"
import { cn } from "@/lib/utils"

export type AsteriskMark = "asterisk" | "star" | "dagger" | "double-dagger"

const MARKS: Record<AsteriskMark, ArtDef> = {
  asterisk: {
    kind: "icon",
    grid: 24,
    parts: [
      ["s", "M12.3 3.6 L11.7 20.4", 1.3],
      ["s", "M4.4 7.9 L19.6 16.3", 1.3],
      ["s", "M19.1 7.5 L5.2 16.6", 1.3],
    ],
    small: [
      ["s", "M12.4 3 L11.6 21", 1.1],
      ["s", "M3.5 7.4 L20.3 16.8", 1.1],
      ["s", "M20 7 L4.4 17", 1.1],
    ],
  },
  star: {
    kind: "icon",
    grid: 24,
    parts: [["s", "M12.2 3.1 L14.8 9.3 L21.3 9.9 L16.4 14.3 L17.9 20.7 L12.1 17.3 L6.3 20.8 L7.7 14.3 L2.8 9.8 L9.4 9.3 L12.5 3.9", 1.15]],
    small: [["s", "M12.2 2.6 L15 9 L21.6 9.7 L16.7 14.2 L18.2 21 L12.1 17.5 L5.9 21.1 L7.4 14.2 L2.4 9.6 L9.2 9 L12.6 3.4", 1.05]],
  },
  dagger: {
    kind: "icon",
    grid: 24,
    parts: [
      ["s", "M12.1 2.9 L11.8 21.3", 1.3],
      ["s", "M7.7 8.3 L16.4 7.8", 1.3],
    ],
    small: [
