  const { formDescriptionId } = useFormField()

  return <p data-slot="form-description" id={formDescriptionId} className={cn("text-sm text-muted-foreground", className)} {...props} />
}

function FormMessage({ className, seed, ref, ...props }: React.ComponentProps<"p"> & { seed?: string | number }) {
  const { error, formMessageId } = useFormField()
  const body = error ? String(error?.message ?? "") : props.children
  const { hostRef, hostProps, node } = useInk({ recipe: fieldErrorRecipe, params: {}, kind: "underline", seed, still: true })
  const mergedRef = useMergedRef<HTMLParagraphElement>(hostRef, ref)

