function Marker({
  className,
  variant = "default",
  tone = "default",
  rule = "line",
  seed,
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof markerVariants> & {
    asChild?: boolean
    tone?: "default" | "new"
    rule?: "line" | "wavy"
    seed?: string | number
  }) {
  const Comp = asChild ? Slot.Root : "div"
  const t: MarkerTone = tone ?? "default"
  const v = variant ?? "default"
