  seed?: string | number
}

function PageTitle({ className, children, ref, as = "h1", underline = "single", seed, ...props }: PageTitleProps) {
  const Comp = as as React.ElementType
  const drawn = underline !== "none"
  const { hostRef, hostProps, node } = useInk({ recipe: titleMarkRecipe, params: { kind: drawn ? underline : "single" }, kind: "mark", seed, still: true })
  const merged = useMergedRef<HTMLElement>(drawn ? hostRef : undefined, ref as React.Ref<HTMLElement>)
  return (
    <Comp
      data-slot="page-title"
      ref={merged}
      {...(drawn && node ? hostProps : {})}
      className={cn("relative isolate w-fit font-script text-[2.6rem] leading-[1.08] font-bold text-balance pb-1.5", className)}
      {...props}
    >
      {drawn ? node : null}
      {children}
    </Comp>
  )
}

function PageDescription({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="page-description" className={cn("max-w-prose text-base text-muted-foreground", className)} {...props} />
}

function PageContent({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="page-content" className={cn("flex flex-1 flex-col gap-4", className)} {...props} />
}

function PageFooter({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="page-footer" className={cn("mt-auto flex items-center justify-between gap-4 pt-2 text-sm text-muted-foreground", className)} {...props} />
