"use client"

import * as React from "react"

import { isCutEdge, edgeInset, edgeName, type EdgeSpec } from "@/lib/ink/paper/edges"
import { PaperDefs } from "@/lib/ink/paper/defs"
import { faceLook, tilesOf } from "@/lib/ink/paper/faces"
import { clip, pin, staple, binderClip, type Accent, type TapeKind } from "@/lib/ink/paper/props"
import { PropSvg } from "@/lib/ink/paper/prop-svg"
import { useInkFaces } from "@/lib/ink/paper/sheet-layers"
import { dropShadow, sheetShadow, tiltFor, type SheetShadowKind } from "@/lib/ink/paper/shadows"
import { RULE_OFFSET_VAR, ruleGeometry, rulesLayer, stockOf, type RuleName, type StockName } from "@/lib/ink/paper/stocks"
import { InkTiles, useDensity, useInk, useInkSeed, useInkTier, useMergedRef } from "@/lib/ink/react"
import { handRulesRecipe, sheetRecipe } from "@/lib/ink/recipes/paper-ink"
import { cn } from "@/lib/utils"
import { Tape } from "@/components/ui/tape"

type FastenerKind = "clip" | "pin" | "staple" | "binder-clip"
type TapePlacement = "corner" | "top" | "both"
type PaperElement = "div" | "section" | "article" | "aside" | "header" | "footer" | "main" | "nav" | "li" | "ul" | "ol" | "form" | "fieldset" | "figure"

type PaperProps = Omit<React.ComponentProps<"div">, "ref"> & {
  ref?: React.Ref<HTMLElement>
  stock?: StockName
  edge?: EdgeSpec
  tilt?: boolean | number
  rules?: RuleName
  tape?: TapePlacement | false
  tapeKind?: TapeKind
  fastener?: FastenerKind | false
  fastenerTone?: "steel" | Accent
  fastenerClassName?: string
  shadow?: "stock" | "none" | SheetShadowKind
  curl?: boolean
  as?: PaperElement
  seed?: string | number
  size?: readonly [number, number]
}

const RULED = new Set<RuleName>(["ruled", "ruled-hand", "index", "pad", "ledger"])

const TAPE_PLACES: Record<TapePlacement, ReadonlyArray<{ className: string; angle: number }>> = {
  corner: [{ className: "-top-2 -left-7", angle: -38 }],
  top: [{ className: "-top-3 left-1/2 -ml-8", angle: -2 }],
  both: [
    { className: "-top-2 -left-7", angle: -38 },
    { className: "-top-2 -right-7", angle: 36 },
  ],
}

const FASTENER_PLACE: Record<FastenerKind, string> = {
  clip: "-top-5 right-8",
  pin: "-top-2 left-1/2 -ml-3",
  staple: "top-2 left-2",
  "binder-clip": "-top-10 left-1/2 -ml-[26px]",
}

const CURL = 34

function Paper({
  className,
  style,
  children,
  ref,
  stock = "paper",
  edge,
  tilt = true,
  rules,
  tape,
  tapeKind = "masking",
  fastener = false,
  fastenerTone,
  fastenerClassName,
  shadow = "stock",
  curl = false,
  as = "div",
  seed: seedProp,
  size,
  ...props
}: PaperProps) {
  const Comp = as as React.ElementType
  const S = stockOf(stock)
  const calm = useDensity() === "calm"
  const requested: EdgeSpec = calm ? "cut" : (edge ?? S.edge)
  const drawn = !isCutEdge(requested) || (curl && !calm)
  const shadowKind = shadow === "stock" ? undefined : shadow
  const sheetParams = React.useMemo(() => ({ stock: S.name, edge: requested, chamfer: curl && !calm ? CURL : undefined, shadow: shadowKind }), [S.name, requested, curl, calm, shadowKind])
  const { hostRef, hostProps, node, seed } = useInkFaces({ recipe: sheetRecipe, params: sheetParams, kind: "sheet", size: drawn ? size : undefined, seed: seedProp })
  const merged = useMergedRef<HTMLElement>(drawn ? hostRef : undefined, ref)
  const ready = drawn && node !== null

  const ruleName: RuleName = rules ?? S.rules
  const handRules = ruleName === "ruled-hand" && !calm
  const hand = useInk({ recipe: handRulesRecipe, params: { paper: S.name === "pad" ? "pad" : "ruled" }, kind: "rules", seed: `${seed}|rules` })
  const layer = React.useMemo(() => rulesLayer(ruleName === "ruled-hand" ? (calm ? "ruled" : "none") : ruleName, { calm }), [ruleName, calm])
  const handOffset = ruleGeometry("ruled", { calm }).offset
  const deg = tilt === false ? 0 : typeof tilt === "number" ? tilt : tiltFor(seed, S.tilt * (RULED.has(ruleName) ? 0.45 : 1))

  const vars: Record<string, string> = ready ? {} : faceLook(S.name, seed).vars
  if (deg) vars["--ll-tilt"] = `${deg}deg`
  if (shadow !== "stock") vars["--ll-sheet-shadow"] = shadow === "none" ? "none" : sheetShadow(shadow)

  const inset = drawn ? Math.ceil(edgeInset(requested)) + 1 : 0
  const places = tape ? TAPE_PLACES[tape] : []
  const cssTiles = ready ? null : tilesOf([S.name])

  return (
    <>
      {cssTiles ? <InkTiles tiles={cssTiles} /> : null}
      <Comp
        data-slot="paper"
        data-stock={S.name}
        data-edge={ready ? (curl && isCutEdge(requested) ? "curl" : edgeName(requested)) : "cut"}
        ref={merged}
        {...(ready ? hostProps : {})}
        className={cn(
          "ll-paper",
          S.stockClass,
          S.toothClass,
          S.shadowClass,
          "calm:[--ll-sheet-shadow:var(--ll-shadow-hair)]",
          className
        )}
        style={{ ...vars, ...style } as React.CSSProperties}
        {...props}
      >
        {drawn ? node : null}
        {layer ? (
          <span
            data-slot="paper-rules"
            aria-hidden="true"
            className="ll-tilt-layer ll-multiply pointer-events-none absolute z-(--ll-z-sheet)"
            style={{ inset, ...layer.style, ...(deg ? { "--ll-tilt": `${deg}deg` } : {}) } as React.CSSProperties}
          />
        ) : null}
        {handRules ? (
          <span
            data-slot="paper-rules"
            aria-hidden="true"
            ref={hand.hostRef}
            {...(hand.node ? hand.hostProps : {})}
            className="ll-tilt-layer ll-multiply pointer-events-none absolute isolate z-(--ll-z-sheet)"
            style={{ inset, translate: `0 calc(${handOffset}px - var(${RULE_OFFSET_VAR}, ${handOffset}px))`, ...(deg ? ({ "--ll-tilt": `${deg}deg` } as React.CSSProperties) : {}) }}
          >
            {hand.node}
          </span>
        ) : null}
        {children}
        {places.map((p, i) => (
          <Tape
            key={i}
            kind={tapeKind}
            length={64}
            height={20}
            angle={p.angle}
            seed={`${seed}:tape:${i}`}
            className={cn("absolute z-(--ll-z-prop) calm:hidden", p.className)}
          />
        ))}
        {fastener ? (
          <Fastener kind={fastener} tone={fastenerTone} seed={`${seed}:fastener`} className={cn("absolute z-(--ll-z-prop) calm:hidden", FASTENER_PLACE[fastener], fastenerClassName)} />
        ) : null}
      </Comp>
    </>
  )
}

type FastenerProps = Omit<React.ComponentProps<"svg">, "children"> & {
  kind?: FastenerKind
  tone?: "steel" | Accent
  size?: number
  seed?: string | number
}

function Fastener({ kind = "clip", tone, size, seed: seedProp, className, style, ...props }: FastenerProps) {
  const seed = useInkSeed(seedProp)
  const tier = useInkTier()
  const calm = useDensity() === "calm"
  const res = React.useMemo(() => {
    const s = `${seed}|${kind}`
    if (kind === "pin") return pin(s, { size: size ?? 24, color: tone && tone !== "steel" ? tone : undefined, tier, calm })
    if (kind === "staple") return staple(s, { length: size ?? 20, tier, calm })
    if (kind === "binder-clip") return binderClip(s, { width: size ?? 52, tier, calm })
    return clip(s, { height: size ?? 62, tone: tone ?? "steel", tier, calm })
  }, [seed, kind, tone, size, tier, calm])
  const jitter = Math.round(tiltFor(`${seed}|at`, 1) * 6)
  return (
    <PropSvg
      res={res}
      kind="sticker"
      data-slot="fastener"
      data-kind={kind}
      className={cn("pointer-events-none relative z-(--ll-z-prop) block shrink-0", className)}
      style={{ filter: dropShadow("prop"), translate: `${jitter}px 0`, ...style }}
      {...props}
    />
  )
}

export { Paper, Fastener, PaperDefs }
export type { PaperProps, FastenerProps, FastenerKind, TapePlacement }

"use client"

import * as React from "react"

import { Paper, type PaperProps } from "@/components/ui/paper"
import { motionIsOff } from "@/hooks/use-live-motion"
import { useInk, useMergedRef } from "@/lib/ink/react"
import type { PaintKey } from "@/lib/ink/paint"
import { PEEL_UNIT, peelFlapRecipe, peelTriggerRecipe } from "@/lib/ink/recipes/peel-corner-ink"
import { clamp } from "@/lib/ink/rng"
import { cn } from "@/lib/utils"

const REST = 0.2
const PEEK = 0.42
const OPEN = 1
const MAX = 1.3
const HIT = 56

type Corner = "bottom-right" | "bottom-left"

interface PeelContextValue {
  open: boolean
  under: string
}

const PeelContext = React.createContext<PeelContextValue | null>(null)

function usePeelCorner(): PeelContextValue {
  const ctx = React.useContext(PeelContext)
  if (!ctx) throw new Error("PeelCorner parts must be used inside <PeelCorner>")
  return ctx
}

type PeelCornerProps = Omit<React.ComponentProps<"div">, "onChange"> & {
  peeled?: boolean
  defaultPeeled?: boolean
  onPeeledChange?: (peeled: boolean) => void
  size?: number
  corner?: Corner
  back?: PaintKey
  label?: string
  seed?: string | number
}

function PeelCorner({
  className,
  children,
  ref,
  peeled: peeledProp,
  defaultPeeled = false,
  onPeeledChange,
  size = PEEL_UNIT,
  corner = "bottom-right",
  back = "paper",
  label = "Peel back the corner",
  seed,
  style,
  ...props
}: PeelCornerProps) {
  const [inner, setInner] = React.useState(defaultPeeled)
  const open = peeledProp ?? inner
  const left = corner === "bottom-left"
  const root = React.useRef<HTMLDivElement | null>(null)
  const k = React.useRef(open ? OPEN : REST)
  const frame = React.useRef(0)
  const drag = React.useRef<{ pointer: number; moved: boolean; startX: number; startY: number } | null>(null)
  const under = React.useId()
  const flap = useInk({ recipe: peelFlapRecipe, params: { back, mirror: left }, kind: "peel-corner-flap", size: [size, size], seed })
  const hit = useInk({ recipe: peelTriggerRecipe, params: {}, kind: "peel-corner-trigger", size: [HIT, HIT], seed: seed === undefined ? undefined : `${seed}|hit` })

  const paint = (v: number) => {
    k.current = v
    root.current?.style.setProperty("--peel-k", v.toFixed(3))
  }
  const tween = (to: number) => {
    cancelAnimationFrame(frame.current)
    const from = k.current
    if (motionIsOff(root.current) || Math.abs(to - from) < 0.005) return paint(to)
    let t0 = -1
    const step = (now: number) => {
      if (t0 < 0) t0 = now
      const t = clamp((now - t0) / 260, 0, 1)
      paint(from + (to - from) * (1 - Math.pow(1 - t, 3)))
      if (t < 1) frame.current = requestAnimationFrame(step)
    }
    frame.current = requestAnimationFrame(step)
  }
  const openNow = React.useRef(open)
  openNow.current = open
  const decline = React.useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  React.useEffect(
    () => () => {
      cancelAnimationFrame(frame.current)
      clearTimeout(decline.current)
    },
    [],
  )
  const settled = React.useRef(open)
  React.useEffect(() => {
    if (settled.current === open) return
    settled.current = open
    tween(open ? OPEN : REST)
  }, [open])

  const set = (v: boolean) => {
    settled.current = v
    if (peeledProp === undefined) setInner(v)
    onPeeledChange?.(v)
    tween(v ? OPEN : REST)
    if (peeledProp !== undefined) {
      clearTimeout(decline.current)
      decline.current = setTimeout(() => {
        if (openNow.current === v) return
        settled.current = openNow.current
        tween(openNow.current ? OPEN : REST)
      }, 0)
    }
  }

  const pull = (e: React.PointerEvent) => {
    const r = root.current?.getBoundingClientRect()
    if (!r) return REST
    const p = left ? (e.clientX - r.left + (r.bottom - e.clientY)) / 2 : (r.right - e.clientX + (r.bottom - e.clientY)) / 2
    return clamp(p / size, 0.05, MAX)
  }
  const down = (e: React.PointerEvent<HTMLButtonElement>) => {
    if ((e.button ?? 0) !== 0) return
    drag.current = { pointer: e.pointerId, moved: false, startX: e.clientX, startY: e.clientY }
    try {
      e.currentTarget.setPointerCapture(e.pointerId)
    } catch {
    }
    cancelAnimationFrame(frame.current)
    root.current?.setAttribute("data-dragging", "")
  }
  const move = (e: React.PointerEvent<HTMLButtonElement>) => {
    const d = drag.current
    if (!d || d.pointer !== e.pointerId) return
    if (Math.hypot(e.clientX - d.startX, e.clientY - d.startY) > 4) d.moved = true
    if (d.moved) paint(pull(e))
  }
  const up = (cancel: boolean) => (e: React.PointerEvent<HTMLButtonElement>) => {
    const d = drag.current
    if (!d || d.pointer !== e.pointerId) return
    drag.current = null
    root.current?.removeAttribute("data-dragging")
    if (cancel) return tween(open ? OPEN : REST)
    if (!d.moved) return set(!open)
    const v = k.current >= 0.62
    if (v !== open) set(v)
    else tween(v ? OPEN : REST)
  }

  const first = React.useRef(String(open ? OPEN : REST)).current
  const vars = { "--peel-size": `${size}px`, "--peel-k": first, "--peel": "calc(var(--peel-k) * var(--peel-size))" } as React.CSSProperties
  const origin = left ? "left-0 origin-bottom-left" : "right-0 origin-bottom-right"

  return (
    <PeelContext.Provider value={{ open, under }}>
      <div
        data-slot="peel-corner"
        data-state={open ? "open" : "closed"}
        data-corner={corner}
        ref={useMergedRef<HTMLDivElement>(root, ref)}
        className={cn("group/peel relative isolate inline-block", className)}
        style={{ ...vars, ...style }}
        {...props}
      >
        {children}
        <span
          aria-hidden="true"
          data-slot="peel-corner-flap"
          ref={flap.hostRef}
          {...flap.hostProps}
          className={cn("pointer-events-none absolute bottom-0 z-2 [scale:var(--peel-k)]", origin)}
          style={{ width: size, height: size }}
        >
          {flap.node}
        </span>
        <button
          type="button"
          data-slot="peel-corner-trigger"
          aria-label={label}
          aria-expanded={open}
          aria-controls={under}
          ref={hit.hostRef}
          {...hit.hostProps}
          onPointerEnter={() => !open && !drag.current && tween(PEEK)}
          onPointerLeave={() => !drag.current && tween(open ? OPEN : REST)}
          onPointerDown={down}
          onPointerMove={move}
          onPointerUp={up(false)}
          onPointerCancel={up(true)}
          onClick={(e) => {
            if (e.detail === 0) set(!open)
          }}
          className={cn("absolute bottom-0 z-3 cursor-grab touch-none active:cursor-grabbing", left ? "left-0" : "right-0")}
          style={{ width: HIT, height: HIT }}
        >
          {hit.node}
        </button>
      </div>
    </PeelContext.Provider>
  )
}

type PageProps = Omit<PaperProps, "ref"> & { ref?: React.Ref<HTMLElement> }

function PeelCornerPage({ className, children, stock = "paper", tilt = false, ...props }: PageProps) {
  usePeelCorner()
  return (
    <Paper
      data-slot="peel-corner-page"
      stock={stock}
      tilt={tilt}
      className={cn(
        "relative z-1 [clip-path:polygon(-40px_-40px,calc(100%+40px)_-40px,calc(100%+40px)_calc(100%-var(--peel)-40px),calc(100%-var(--peel)-40px)_calc(100%+40px),-40px_calc(100%+40px))]",
        "group-data-[corner=bottom-left]/peel:[clip-path:polygon(-40px_-40px,calc(100%+40px)_-40px,calc(100%+40px)_calc(100%+40px),calc(var(--peel)+40px)_calc(100%+40px),-40px_calc(100%-var(--peel)-40px))]",
        "p-5",
        className,
      )}
      {...props}
    >
      {children}
    </Paper>
  )
}

function PeelCornerUnder({ className, children, stock = "kraft", ...props }: PageProps) {
  const { open, under } = usePeelCorner()
  return (
    <Paper
      id={under}
      data-slot="peel-corner-under"
      data-state={open ? "open" : "closed"}
      stock={stock}
      tilt={false}
      inert={!open}
      aria-hidden={!open || undefined}
      className={cn("absolute inset-0 z-0 flex items-end justify-end p-3 group-data-[corner=bottom-left]/peel:justify-start", className)}
      {...props}
    >
      {children}
    </Paper>
  )
}

export { PeelCorner, PeelCornerPage, PeelCornerUnder, usePeelCorner }
export type { PeelCornerProps }

