function Toaster({ className, toastOptions, decoration = "none", theme = "light", icons, style, portal = false, ...props }: LooseleafToasterProps) {
  const scope = useInkScope()
  const [mounted, setMounted] = React.useState(false)
  React.useEffect(() => {
