  }, [portal])
  const user = toastOptions?.classNames ?? {}
  const merged = Object.fromEntries(
    (Object.keys({ ...BASE, ...user }) as Array<keyof ToastClassNames>).map((k) => [k, cn(BASE[k], k === "content" && decoration !== "none" && (decoration === "tape" ? TAPE : PIN), user[k])])
