function Squiggle({
  kind = "wavy",
  orientation = "horizontal",
  decorative = true,
  tone = "ink",
  weight = "regular",
  animate = false,
  show = true,
  delay,
  seed,
  className,
  style,
  ref,
  ...props
}: Omit<React.ComponentProps<"div">, "children"> & {
  kind?: SquiggleKind
