"use client"

import * as React from "react"

import { Icon } from "@/components/ui/icon"
import { useInk, useMergedRef } from "@/lib/ink/react"
import { stepperRecipe, stepperTallyRecipe, tallyWidth, TALLY_H } from "@/lib/ink/recipes/stepper-ink"
import { cn } from "@/lib/utils"

type Direction = 1 | -1

interface StepperContextValue {
  value: number | undefined
  min?: number
  max?: number
  step: number
  disabled: boolean
  readOnly: boolean
  invalid: boolean
  atMin: boolean
  atMax: boolean
  holding: 0 | Direction
  motion: { dir: Direction; n: number } | null
  format: (n: number) => string
  commitText: (text: string) => boolean
  adjust: (delta: number) => void
  jump: (to: number | undefined) => void
  startHold: (dir: Direction) => void
  stopHold: () => void
  largeStep: number
  wheel: boolean
  hiddenName: string | undefined
  inputProps: { id?: string; name?: string; form?: string; required?: boolean; "aria-label"?: string; "aria-labelledby"?: string; "aria-describedby"?: string }
  inputRef: React.RefObject<HTMLInputElement | null>
  reset: () => void
  nudge: () => void
}

const StepperContext = React.createContext<StepperContextValue | null>(null)

function useStepper(): StepperContextValue {
  const ctx = React.useContext(StepperContext)
  if (!ctx) throw new Error("Stepper parts must be used inside <Stepper>")
  return ctx
}

const decimals = (n: number | undefined): number => {
  if (n === undefined || !Number.isFinite(n)) return 0
  const s = String(n)
  if (s.includes("e-")) return Number(s.split("e-")[1])
  const i = s.indexOf(".")
  return i < 0 ? 0 : s.length - i - 1
}

function parseNumber(text: string): number | undefined {
  const t = text
    .trim()
    .replace(/[\u0660-\u0669]/g, (d) => String(d.charCodeAt(0) - 0x660))
    .replace(/[\u06f0-\u06f9]/g, (d) => String(d.charCodeAt(0) - 0x6f0))
    .replace(/\u066b/g, ".")
    .replace(/\u066c/g, ",")
    .replace(/[\s\u00a0\u202f']/g, "")
  const m = /^([-+\u2212]?)([\d.,]*)$/.exec(t)
  if (!m || !/\d/.test(m[2])) return undefined
  const body = m[2]
  const dots = body.split(".").length - 1
  const commas = body.split(",").length - 1
  const point = dots && commas ? (body.lastIndexOf(".") > body.lastIndexOf(",") ? "." : ",") : dots === 1 && !commas ? "." : commas === 1 && !dots ? "," : ""
  const group = point === "." ? "," : point === "," ? "." : dots > 1 ? "." : commas > 1 ? "," : ""
  const at = point ? body.lastIndexOf(point) : -1
  const whole = at < 0 ? body : body.slice(0, at)
  const frac = at < 0 ? "" : body.slice(at + 1)
  if (!(group ? new RegExp(`^(\\d{1,3}(\\${group}\\d{3})*)?$`) : /^\d*$/).test(whole) || !/^\d*$/.test(frac)) return undefined
  const n = Number(`${whole.replace(/[.,]/g, "") || "0"}${frac ? `.${frac}` : ""}`)
  return Number.isFinite(n) ? (m[1] === "-" || m[1] === "\u2212" ? -n : n) : undefined
}

const HOLD_DELAY = 420
const HOLD_EVERY = 90

interface StepperProps extends Omit<React.ComponentProps<"div">, "defaultValue" | "onChange" | "id"> {
  value?: number | undefined
  defaultValue?: number
  onValueChange?: (value: number | undefined) => void
  min?: number
  max?: number
  step?: number
  largeStep?: number
  snap?: boolean
  precision?: number
  format?: (value: number) => string
  parse?: (text: string) => number | undefined
  wheel?: boolean
  id?: string
  name?: string
  form?: string
  required?: boolean
  disabled?: boolean
  readOnly?: boolean
  invalid?: boolean
  "aria-label"?: string
  "aria-labelledby"?: string
  "aria-describedby"?: string
  seed?: string | number
}

function Stepper(props: StepperProps) {
  const {
    value: _value,
    defaultValue,
    onValueChange,
    min,
    max,
    step: stepProp = 1,
    largeStep: largeStepProp,
    snap = false,
    precision: precisionProp,
    format: formatProp,
    parse: parseProp,
    wheel = false,
    id,
    name,
    form,
    required,
    disabled = false,
    readOnly = false,
    invalid = false,
    "aria-label": ariaLabel,
    "aria-labelledby": ariaLabelledby,
    "aria-describedby": ariaDescribedby,
    seed,
    className,
    children,
    ref,
    ...rest
  } = props
  void _value
  const step = Number.isFinite(stepProp) && stepProp > 0 ? stepProp : 1
  const controlled = "value" in props
  const [inner, setInner] = React.useState<number | undefined>(defaultValue)
  const rawValue = controlled ? props.value : inner
  const value = rawValue !== undefined && Number.isFinite(rawValue) ? rawValue : undefined
  const latest = React.useRef(value)
  latest.current = value
  const [motion, setMotion] = React.useState<StepperContextValue["motion"]>(null)
  const [holding, setHolding] = React.useState<0 | Direction>(0)
  const [limit, setLimit] = React.useState(0)
  const nudge = React.useCallback(() => setLimit((n) => n + 1), [])
  const inputRef = React.useRef<HTMLInputElement | null>(null)

  const places = precisionProp ?? Math.max(decimals(step), decimals(min))
  const round = React.useCallback((n: number, from?: number) => Number(n.toFixed(Math.min(Math.max(places, decimals(from)), 12))), [places])
  const clamp = React.useCallback((n: number) => Math.min(max ?? Infinity, Math.max(min ?? -Infinity, n)), [min, max])
  const format = React.useCallback((n: number) => (formatProp ? formatProp(n) : precisionProp !== undefined ? n.toFixed(precisionProp) : String(n)), [formatProp, precisionProp])
  const parse = React.useCallback(
    (text: string): number | undefined => {
      if (parseProp) return parseProp(text)
      return parseNumber(text)
    },
    [parseProp]
  )
  const largeStep = largeStepProp ?? step * 10

  const set = React.useCallback(
    (next: number | undefined) => {
      latest.current = next
      if (!controlled) setInner(next)
      onValueChange?.(next)
    },
    [controlled, onValueChange]
  )
  const snapTo = React.useCallback(
    (n: number) => {
      if (!snap) return n
      const origin = min ?? 0
      return origin + Math.round((n - origin) / step) * step
    },
    [snap, min, step]
  )
  const adjust = React.useCallback(
    (delta: number) => {
      if (disabled || readOnly) return
      const from = latest.current
      const next = clamp(round(snapTo((from ?? 0) + delta), from))
      if (next === from) {
        if (delta !== 0) nudge()
        return
      }
      setMotion((m) => ({ dir: delta > 0 ? 1 : -1, n: (m?.n ?? 0) + 1 }))
      set(next)
    },
    [disabled, readOnly, clamp, round, snapTo, set, nudge]
  )
  const jump = React.useCallback(
    (to: number | undefined) => {
      if (disabled || readOnly || to === undefined || to === latest.current) return
      setMotion((m) => ({ dir: latest.current === undefined || to > latest.current ? 1 : -1, n: (m?.n ?? 0) + 1 }))
      set(to)
    },
    [disabled, readOnly, set]
  )
  const commitText = React.useCallback(
    (text: string): boolean => {
      if (text.trim() === "") {
        if (required) return false
        set(undefined)
        return true
      }
      const n = parse(text)
      if (n === undefined || !Number.isFinite(n)) return false
      const next = clamp(Number(snapTo(n).toPrecision(12)))
      if (next !== latest.current) set(next)
      return true
    },
    [set, parse, clamp, round, snapTo, required]
  )

  const timers = React.useRef<{ wait?: number; run?: number; count: number }>({ count: 0 })
  const stopHold = React.useCallback(() => {
    window.clearTimeout(timers.current.wait)
    window.clearInterval(timers.current.run)
    timers.current = { count: 0 }
    setHolding(0)
  }, [])
  const startHold = React.useCallback(
    (dir: Direction) => {
      stopHold()
      if (disabled || readOnly) return
      adjust(dir * step)
      setHolding(dir)
      const tickOnce = () => {
        const before = latest.current
        adjust(dir * step * (timers.current.count > 24 ? 5 : 1))
        timers.current.count++
        if (latest.current === before) stopHold()
      }
      timers.current.wait = window.setTimeout(() => {
        timers.current.run = window.setInterval(tickOnce, HOLD_EVERY)
      }, HOLD_DELAY)
    },
    [stopHold, disabled, readOnly, adjust, step]
  )
  React.useEffect(() => stopHold, [stopHold])

  const reset = React.useCallback(() => {
    if (!controlled) {
      latest.current = defaultValue
      setInner(defaultValue)
    }
  }, [controlled, defaultValue])

  const hasValue = value !== undefined
  const atMin = hasValue && min !== undefined && value <= min
  const atMax = hasValue && max !== undefined && value >= max

  const ctx = React.useMemo<StepperContextValue>(
    () => ({
      value, min, max, step, disabled, readOnly, invalid, atMin, atMax, holding, motion, format, commitText, adjust, jump, startHold, stopHold, largeStep, wheel,
      hiddenName: formatProp ? name : undefined,
      inputProps: { id, name: formatProp ? undefined : name, form, required, "aria-label": ariaLabel, "aria-labelledby": ariaLabelledby, "aria-describedby": ariaDescribedby },
      inputRef, reset, nudge,
    }),
    [value, min, max, step, disabled, readOnly, invalid, atMin, atMax, holding, motion, format, commitText, adjust, jump, startHold, stopHold, largeStep, wheel, formatProp, id, name, form, required, ariaLabel, ariaLabelledby, ariaDescribedby, reset, nudge]
  )

  const { hostRef, hostProps, node } = useInk({ recipe: stepperRecipe, params: { disabled, invalid: invalid && !disabled, plain: false }, kind: "field", seed, still: true })
  return (
    <StepperContext.Provider value={ctx}>
      <style href="ll-stepper" precedence="low">
        {STEPPER_CSS}
      </style>
      <div
        data-slot="stepper"
        role="group"
        data-ink-focus="within"
        data-disabled={disabled ? "" : undefined}
        data-invalid={invalid ? "" : undefined}
        data-limit={limit ? (limit % 2 ? "a" : "b") : undefined}
        ref={useMergedRef<HTMLDivElement>(hostRef, ref)}
        {...hostProps}
        className={cn("relative isolate inline-flex h-9 w-fit items-stretch font-hand text-base text-(--ll-input-ink) compact:h-8 calm:h-7", className)}
        {...rest}
      >
        {node}
        {children ?? (
          <>
            <StepperDecrement />
            <StepperInput />
            <StepperIncrement />
          </>
        )}
      </div>
    </StepperContext.Provider>
  )
}

const STEPPER_CSS =
  "@keyframes ll-step-shake-a{0%{rotate:0deg}20%{rotate:-1.6deg}45%{rotate:1.3deg}70%{rotate:-.7deg}100%{rotate:0deg}}@keyframes ll-step-shake-b{0%{rotate:0deg}20%{rotate:-1.6deg}45%{rotate:1.3deg}70%{rotate:-.7deg}100%{rotate:0deg}}" +
  '[data-slot=stepper][data-limit=a]{animation:ll-step-shake-a var(--ll-dur-toss) ease-out both}[data-slot=stepper][data-limit=b]{animation:ll-step-shake-b var(--ll-dur-toss) ease-out both}' +
  "@keyframes ll-step-up-a{0%{translate:0 38%;opacity:.35}100%{translate:0 0;opacity:1}}@keyframes ll-step-up-b{0%{translate:0 38%;opacity:.35}100%{translate:0 0;opacity:1}}" +
  "@keyframes ll-step-down-a{0%{translate:0 -38%;opacity:.35}100%{translate:0 0;opacity:1}}@keyframes ll-step-down-b{0%{translate:0 -38%;opacity:.35}100%{translate:0 0;opacity:1}}" +
  '[data-slot=stepper-input][data-tick="up-a"]{animation:ll-step-up-a var(--ll-dur-pop) var(--ll-ease-settle) both}[data-slot=stepper-input][data-tick="up-b"]{animation:ll-step-up-b var(--ll-dur-pop) var(--ll-ease-settle) both}' +
  '[data-slot=stepper-input][data-tick="down-a"]{animation:ll-step-down-a var(--ll-dur-pop) var(--ll-ease-settle) both}[data-slot=stepper-input][data-tick="down-b"]{animation:ll-step-down-b var(--ll-dur-pop) var(--ll-ease-settle) both}'

const BUTTON =
  "relative m-[3px] calm:m-0.5 grid aspect-square shrink-0 cursor-default place-items-center text-ink outline-hidden select-none hover:ll-swipe focus-visible:ll-swipe focus-visible:[outline:2px_solid_var(--ll-focus)] focus-visible:outline-offset-[-2px] active:[background:color-mix(in_srgb,var(--ll-hi)_85%,transparent)] data-[holding=true]:[background:color-mix(in_srgb,var(--ll-hi)_85%,transparent)] aria-disabled:pointer-events-none aria-disabled:text-pencil-text [&_svg]:pointer-events-none"

function StepperButton({ direction, className, children, onPointerDown, onClick, onKeyDown, ...props }: React.ComponentProps<"button"> & { direction: Direction }) {
  const ctx = useStepper()
  const off = ctx.disabled || ctx.readOnly || (direction === 1 ? ctx.atMax : ctx.atMin)
  return (
    <button
      type="button"
      tabIndex={-1}
      data-holding={ctx.holding === direction || undefined}
      aria-disabled={off || undefined}
      disabled={ctx.disabled}
      onMouseDown={(e) => e.preventDefault()}
      onPointerDown={(e) => {
        onPointerDown?.(e)
        if (e.defaultPrevented || (e.pointerType === "mouse" && e.button !== 0)) return
        if (off) {
          if (!ctx.disabled && !ctx.readOnly) ctx.nudge()
          return
        }
        ctx.startHold(direction)
        const stop = () => {
          ctx.stopHold()
          window.removeEventListener("pointerup", stop)
          window.removeEventListener("pointercancel", stop)
        }
        window.addEventListener("pointerup", stop)
        window.addEventListener("pointercancel", stop)
      }}
      onClick={(e) => {
        onClick?.(e)
        if (e.defaultPrevented || e.detail !== 0 || off) return
        ctx.adjust(direction * ctx.step)
      }}
      onKeyDown={(e) => {
        onKeyDown?.(e)
        e.stopPropagation()
      }}
      className={cn(BUTTON, className)}
      {...props}
    >
      {children}
    </button>
  )
}

function StepperDecrement({ className, children, "aria-label": label = "Decrease", ...props }: React.ComponentProps<"button">) {
  return (
    <StepperButton direction={-1} data-slot="stepper-decrement" aria-label={label} className={className} {...props}>
      {children ?? <Icon name="minus" size={18} />}
    </StepperButton>
  )
}

function StepperIncrement({ className, children, "aria-label": label = "Increase", ...props }: React.ComponentProps<"button">) {
  return (
    <StepperButton direction={1} data-slot="stepper-increment" aria-label={label} className={className} {...props}>
      {children ?? <Icon name="plus" size={18} />}
    </StepperButton>
  )
}

function StepperInput({ className, style, ref, onKeyDown, onBlur, onChange, ...props }: Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "type">) {
  const ctx = useStepper()
  const { inputRef, inputProps } = ctx
  const [draft, setDraft] = React.useState<{ text: string; base: string } | null>(null)
  const text = ctx.value === undefined ? "" : ctx.format(ctx.value)
  const shown = draft && draft.base === text ? draft.text : text

  const { adjust, jump, step, largeStep, min, max, wheel, disabled, reset } = ctx
  React.useEffect(() => {
    const el = inputRef.current
    if (!el || !wheel || disabled) return
    const onWheel = (e: WheelEvent) => {
      if (document.activeElement !== el || e.deltaY === 0) return
      e.preventDefault()
      adjust(e.deltaY < 0 ? step : -step)
    }
    el.addEventListener("wheel", onWheel, { passive: false })
    return () => el.removeEventListener("wheel", onWheel)
  }, [inputRef, wheel, disabled, adjust, step])
  React.useEffect(() => {
    const form = inputRef.current?.form
    if (!form) return
    const onReset = () => {
      setDraft(null)
      reset()
    }
    form.addEventListener("reset", onReset)
    return () => form.removeEventListener("reset", onReset)
  }, [inputRef, reset])

  const commit = (): void => {
    if (!draft || draft.base !== text) return
    if (ctx.commitText(draft.text)) setDraft(null)
    else setDraft(null)
  }
  const tick = ctx.motion ? `${ctx.motion.dir === 1 ? "up" : "down"}-${ctx.motion.n % 2 ? "a" : "b"}` : undefined
  return (
    <>
      <input
        type="text"
        inputMode="decimal"
        role="spinbutton"
        autoComplete="off"
        spellCheck={false}
        data-slot="stepper-input"
        data-tick={tick}
        aria-valuenow={ctx.value}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuetext={ctx.value === undefined ? undefined : text}
        aria-invalid={ctx.invalid || undefined}
        disabled={ctx.disabled}
        readOnly={ctx.readOnly}
        value={shown}
        style={{ minWidth: `${Math.max(3, shown.length) + 1}ch`, ...style }}
        ref={useMergedRef<HTMLInputElement>(inputRef, ref)}
        {...inputProps}
        onChange={(e) => {
          onChange?.(e)
          setDraft({ text: e.target.value, base: text })
        }}
        onBlur={(e) => {
          onBlur?.(e)
          commit()
        }}
        onKeyDown={(e) => {
          onKeyDown?.(e)
          if (e.defaultPrevented || ctx.disabled) return
          const big = e.shiftKey ? largeStep : step
          switch (e.key) {
            case "ArrowUp":
              e.preventDefault()
              setDraft(null)
              adjust(big)
              break
            case "ArrowDown":
              e.preventDefault()
              setDraft(null)
              adjust(-big)
              break
            case "PageUp":
              e.preventDefault()
              setDraft(null)
              adjust(largeStep)
              break
            case "PageDown":
              e.preventDefault()
              setDraft(null)
              adjust(-largeStep)
              break
            case "Home":
              if (min !== undefined) {
                e.preventDefault()
                setDraft(null)
                jump(min)
              }
              break
            case "End":
              if (max !== undefined) {
                e.preventDefault()
                setDraft(null)
                jump(max)
              }
              break
            case "Enter":
              commit()
              break
            case "Escape":
              if (draft) {
                e.preventDefault()
                setDraft(null)
              }
              break
          }
        }}
        className={cn(
          "h-full w-16 min-w-0 flex-1 bg-transparent px-1 text-center font-script text-[1.65rem] leading-none font-bold text-(--ll-input-ink) caret-(--ll-caret) outline-hidden [appearance:textfield] disabled:cursor-not-allowed disabled:text-pencil-text calm:text-[1.35rem]",
          className
        )}
        {...props}
      />
      {ctx.hiddenName ? <input type="hidden" name={ctx.hiddenName} form={inputProps.form} value={ctx.value === undefined ? "" : String(ctx.value)} disabled={ctx.disabled} /> : null}
    </>
  )
}

function StepperTally({ className, style, max = 20, seed, value: valueProp, ...props }: Omit<React.ComponentProps<"span">, "children" | "value"> & { max?: number; seed?: string | number; value?: number }) {
  const ctx = React.useContext(StepperContext)
  const shown = valueProp ?? ctx?.value ?? 0
  const count = Math.max(0, Math.min(Number.isFinite(shown) ? Math.floor(shown) : 0, max))
  const width = tallyWidth(Math.max(count, 1))
  const { hostRef, hostProps, node } = useInk({ recipe: stepperTallyRecipe, params: { count }, kind: "tally", size: [width, TALLY_H + 4], seed, still: true })
  return (
    <span data-slot="stepper-tally" aria-hidden="true" ref={hostRef} {...hostProps} style={{ width, ...style }} className={cn("relative isolate inline-block h-5 shrink-0 text-ink", className)} {...props}>
      {count > 0 ? node : null}
    </span>
  )
}

export { Stepper, StepperDecrement, StepperInput, StepperIncrement, StepperTally, useStepper }
export type { StepperProps }

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import { Paper, type PaperProps } from "@/components/ui/paper"
import { useEnsureInkDefs, useInk, useInkSeed, useMergedRef } from "@/lib/ink/react"
import { HANDLE, composeBoardSvg, stickerBoardItemRecipe, wholeItems, type StickerBoardItem } from "@/lib/ink/recipes/sticker-board-ink"
import { stickerFace, stickerLabel } from "@/lib/ink/recipes/sticker-ink"
import { clamp, hashSeed } from "@/lib/ink/rng"
import { cn } from "@/lib/utils"

const STEP = 8
const BIG_STEP = 32
const TURN = 5
const BIG_TURN = 15
const ZOOM = 1.1
const BIG_ZOOM = 1.25
const DEFAULT_MIN = 0.3
const DEFAULT_MAX = 3

const turnTo = (deg: number): number => {
  const a = Math.round((((deg + 180) % 360) + 360) % 360 * 10) / 10 - 180
  return a === -180 ? 180 : Math.round(a * 10) / 10
}
const round2 = (v: number): number => Math.round(v * 100) / 100

type Reorder = "front" | "back" | "forward" | "backward"

function reorderSticker(items: readonly StickerBoardItem[], id: string, how: Reorder): StickerBoardItem[] {
  const zOf = (s: StickerBoardItem) => (Number.isFinite(s.z) ? s.z : 0)
  const sorted = [...items].sort((a, b) => zOf(a) - zOf(b))
  const i = sorted.findIndex((s) => s.id === id)
  if (i < 0) return items as StickerBoardItem[]
  const [it] = sorted.splice(i, 1)
  const to = how === "front" ? sorted.length : how === "back" ? 0 : how === "forward" ? Math.min(i + 1, sorted.length) : Math.max(i - 1, 0)
  if (to === i && how !== "front" && how !== "back") return items as StickerBoardItem[]
  sorted.splice(to, 0, it)
  const rank = new Map(sorted.map((s, k) => [s.id, k]))
  const next = items.map((s) => ({ ...s, z: rank.get(s.id) ?? s.z }))
  return next.every((s, k) => s.z === items[k].z) ? (items as StickerBoardItem[]) : next
}

interface AddOptions {
  x?: number
  y?: number
  rot?: number
  scale?: number
  id?: string
  canvas?: { width: number; height: number }
}

function addSticker(items: readonly StickerBoardItem[], name: string, o: AddOptions = {}): StickerBoardItem[] {
  const used = new Set(items.map((s) => s.id))
  let k = 1
  while (used.has(`${name}-${k}`)) k++
  const id = o.id && !used.has(o.id) ? o.id : `${name}-${k}`
  const cx = o.x ?? (o.canvas ? o.canvas.width / 2 : 160) + ((items.length % 5) - 2) * 18
  const cy = o.y ?? (o.canvas ? o.canvas.height / 2 : 120) + ((items.length % 4) - 1.5) * 14
  const rot = o.rot ?? Math.round(((hashSeed(id) % 1600) / 100 - 8) * 10) / 10
  const z = items.reduce((m, s) => Math.max(m, Number.isFinite(s.z) ? s.z : 0), -1) + 1
  return [...items, { id, name, x: Math.round(cx), y: Math.round(cy), rot, scale: o.scale ?? 1, z }]
}

function boardPoint(root: Element | null | undefined, clientX: number, clientY: number): { x: number; y: number; inside: boolean } | null {
  const canvas = root?.matches?.('[data-slot="sticker-board-canvas"]') ? root : root?.querySelector?.('[data-slot="sticker-board-canvas"]')
  if (!canvas) return null
  const r = canvas.getBoundingClientRect()
  return { x: Math.round(clientX - r.left), y: Math.round(clientY - r.top), inside: clientX >= r.left && clientX <= r.left + r.width && clientY >= r.top && clientY <= r.top + r.height }
}

type BoundsMode = "center" | "inside" | "none"

function keepIn(x: number, y: number, art: { w: number; h: number; rot: number; scale: number }, canvas: { w: number; h: number }, mode: BoundsMode): [number, number] {
  if (mode === "none" || !canvas.w || !canvas.h) return [x, y]
  if (mode === "center") return [clamp(x, 0, canvas.w), clamp(y, 0, canvas.h)]
  const a = (art.rot * Math.PI) / 180
  const c = Math.abs(Math.cos(a)), s = Math.abs(Math.sin(a))
  const ex = Math.min(canvas.w / 2, (art.w * art.scale * c + art.h * art.scale * s) / 2)
  const ey = Math.min(canvas.h / 2, (art.w * art.scale * s + art.h * art.scale * c) / 2)
  return [clamp(x, ex, canvas.w - ex), clamp(y, ey, canvas.h - ey)]
}

const DROP =
  "drop-shadow(calc(var(--sb-dx) * (1px + 4px * var(--sb-lift))) calc(var(--sb-dy) * (1px + 4px * var(--sb-lift))) calc(0.6px + 2.4px * var(--sb-lift)) rgb(var(--ll-shade) / calc(0.26 * var(--ll-shadow-k)))) " +
  "drop-shadow(calc(var(--sb-dx) * (3px + 11px * var(--sb-lift))) calc(var(--sb-dy) * (3px + 11px * var(--sb-lift))) calc(3px + 7px * var(--sb-lift)) rgb(var(--ll-shade) / calc(0.14 * var(--ll-shadow-k))))"

const down = (rot: number) => {
  const a = (rot * Math.PI) / 180
  return { dx: Math.round(Math.sin(a) * 1000) / 1000, dy: Math.round(Math.cos(a) * 1000) / 1000 }
}

interface StickerBoardContextValue {
  items: readonly StickerBoardItem[]
  selectedId: string | null
  select(id: string | null): void
  commit(next: StickerBoardItem[], message?: string): void
  patch(id: string, change: Partial<StickerBoardItem>, message?: string): void
  remove(id: string): void
  duplicate(id: string): void
  reorder(id: string, how: Reorder): void
  turn(id: string, deg: number): void
  resize(id: string, factor: number): void
  exportBoard(): void
  size: number
  minScale: number
  maxScale: number
  bounds: BoundsMode
  editable: boolean
  canvas(): { w: number; h: number }
  registerCanvas(el: HTMLElement | null): void
  say(message: string): void
  help: string
  canvasId: string
  label: string
}

const StickerBoardContext = React.createContext<StickerBoardContextValue | null>(null)

function useStickerBoard(): StickerBoardContextValue {
  const ctx = React.useContext(StickerBoardContext)
  if (!ctx) throw new Error("Sticker board parts must be used inside <StickerBoard>")
  return ctx
}

interface StickerBoardExport {
  items: StickerBoardItem[]
  json: string
  svg: string
  width: number
  height: number
  png(scale?: number): Promise<Blob>
}

function resolveTokens(svg: string, el: Element): string {
  if (typeof getComputedStyle !== "function") return svg
  const cs = getComputedStyle(el)
  return svg.replace(/var\((--[a-z0-9-]+)\)/gi, (whole, name: string) => cs.getPropertyValue(name).trim() || whole)
}

function rasterise(svg: string, width: number, height: number, scale: number): Promise<Blob> {
  return new Promise((resolve, reject) => {
    const img = new Image()
    const url = URL.createObjectURL(new Blob([svg], { type: "image/svg+xml;charset=utf-8" }))
    img.onload = () => {
      const canvas = document.createElement("canvas")
      canvas.width = Math.round(width * scale)
      canvas.height = Math.round(height * scale)
      const g = canvas.getContext("2d")
      if (!g) return reject(new Error("No 2d canvas"))
      g.drawImage(img, 0, 0, canvas.width, canvas.height)
      URL.revokeObjectURL(url)
      canvas.toBlob((b) => (b ? resolve(b) : reject(new Error("The canvas gave no image"))), "image/png")
    }
    img.onerror = () => {
      URL.revokeObjectURL(url)
      reject(new Error("The svg could not be drawn"))
    }
    img.src = url
  })
}

type StickerBoardProps = Omit<React.ComponentProps<"div">, "defaultValue" | "onChange"> & {
  value?: StickerBoardItem[]
  defaultValue?: StickerBoardItem[]
  onValueChange?: (value: StickerBoardItem[]) => void
  selectedId?: string | null
  defaultSelectedId?: string | null
  onSelectedIdChange?: (id: string | null) => void
  size?: number
  minScale?: number
  maxScale?: number
  bounds?: BoundsMode
  readOnly?: boolean
  disabled?: boolean
  label?: string
  onExport?: (data: StickerBoardExport) => void
}

function StickerBoard({
  className,
  children,
  ref,
  value,
  defaultValue,
  onValueChange,
  selectedId: selectedProp,
  defaultSelectedId = null,
  onSelectedIdChange,
  size = 96,
  minScale = DEFAULT_MIN,
  maxScale = DEFAULT_MAX,
  bounds = "center",
  readOnly = false,
  disabled = false,
  label = "Sticker board",
  onExport,
  ...props
}: StickerBoardProps) {
  const [inner, setInner] = React.useState<StickerBoardItem[]>(defaultValue ?? [])
  const controlled = value !== undefined
  const raw = controlled ? value : inner
  const items = React.useMemo(() => wholeItems(raw), [raw])
  const latest = React.useRef(items)
  latest.current = items
  const [innerSel, setInnerSel] = React.useState<string | null>(defaultSelectedId)
  const selControlled = selectedProp !== undefined
  const sel = selControlled ? selectedProp : innerSel
  const selectedId = sel !== null && items.some((s) => s.id === sel) ? sel : null
  const canvasEl = React.useRef<HTMLElement | null>(null)
  const help = React.useId()
  const canvasId = React.useId()
  const [status, setStatus] = React.useState("")
  const said = React.useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  React.useEffect(() => () => clearTimeout(said.current), [])

  const say = React.useCallback((message: string) => {
    clearTimeout(said.current)
    said.current = setTimeout(() => setStatus(message), 300)
  }, [])
  const select = React.useCallback(
    (id: string | null) => {
      if (!selControlled) setInnerSel(id)
      onSelectedIdChange?.(id)
    },
    [selControlled, onSelectedIdChange]
  )
  const commit = React.useCallback(
    (next: StickerBoardItem[], message?: string) => {
      latest.current = next
      if (!controlled) setInner(next)
      onValueChange?.(next)
      if (message) say(message)
    },
    [controlled, onValueChange, say]
  )
  const find = (id: string) => latest.current.find((s) => s.id === id)
  const nameOf = (id: string) => {
    const it = find(id)
    return it ? stickerLabel(it.name) : id
  }
  const patch = React.useCallback(
    (id: string, change: Partial<StickerBoardItem>, message?: string) => commit(latest.current.map((s) => (s.id === id ? { ...s, ...change } : s)), message),
    [commit]
  )

  const api = React.useMemo<StickerBoardContextValue>(() => {
    const canvas = () => ({ w: canvasEl.current?.offsetWidth ?? 0, h: canvasEl.current?.offsetHeight ?? 0 })
    const doExport = () => {
      const el = canvasEl.current
      const { w, h } = canvas()
      const width = w || 640, height = h || 400
      const build = () => composeBoardSvg(latest.current, { width, height, size, resolve: el ? (s) => resolveTokens(s, el) : undefined })
      const svg = build()
      const data: StickerBoardExport = {
        items: latest.current,
        json: JSON.stringify(latest.current, null, 2),
        svg,
        width,
        height,
        png: (scale = 2) => rasterise(svg, width, height, scale),
      }
      if (onExport) return onExport(data)
      if (typeof document === "undefined") return
      const url = URL.createObjectURL(new Blob([svg], { type: "image/svg+xml" }))
      const a = document.createElement("a")
      a.href = url
      a.download = "stickers.svg"
      document.body.append(a)
      a.click()
      a.remove()
      setTimeout(() => URL.revokeObjectURL(url), 1000)
    }
    return {
      items,
      selectedId,
      select,
      commit,
      patch,
      remove(id) {
        const at = latest.current.findIndex((s) => s.id === id)
        if (at < 0) return
        const name = nameOf(id)
        commit(latest.current.filter((s) => s.id !== id), `${name} removed.`)
        select(null)
      },
      duplicate(id) {
        const it = find(id)
        if (!it) return
        const next = addSticker(latest.current, it.name, { x: it.x + 20, y: it.y + 20, rot: it.rot, scale: it.scale })
        commit(next, `${nameOf(id)} duplicated.`)
        select(next[next.length - 1].id)
      },
      reorder(id, how) {
        const next = reorderSticker(latest.current, id, how)
        if (next === latest.current) return say(`${nameOf(id)} is already ${how === "forward" || how === "front" ? "on top" : "at the back"}.`)
        const word = { front: "brought to the front", back: "sent to the back", forward: "brought forward", backward: "sent backward" }[how]
        commit(next, `${nameOf(id)} ${word}.`)
      },
      turn(id, deg) {
        const it = find(id)
        if (!it) return
        const rot = turnTo(it.rot + deg)
        patch(id, { rot }, `${nameOf(id)} turned to ${rot} degrees.`)
      },
      resize(id, factor) {
        const it = find(id)
        if (!it) return
        const scale = clamp(round2(it.scale * factor), minScale, maxScale)
        if (scale === it.scale) return say(`${nameOf(id)} is as ${factor > 1 ? "big" : "small"} as it goes.`)
        patch(id, { scale }, `${nameOf(id)} at ${Math.round(scale * 100)} percent.`)
      },
      exportBoard: doExport,
      size,
      minScale,
      maxScale,
      bounds,
      editable: !readOnly && !disabled,
      canvas,
      registerCanvas: (el) => {
        canvasEl.current = el
      },
      say,
      help,
      canvasId,
      label,
    }
  }, [items, selectedId, select, commit, patch, say, size, minScale, maxScale, bounds, readOnly, disabled, help, canvasId, label, onExport])

  return (
    <StickerBoardContext.Provider value={api}>
      <div data-slot="sticker-board" data-disabled={disabled ? "" : undefined} ref={ref} className={cn("flex min-w-0 flex-col gap-3", disabled && "opacity-70", className)} {...props}>
        {children ?? (
          <>
            <StickerBoardCanvas className="flex-1" />
            <StickerBoardToolbar />
          </>
        )}
        {!readOnly && !disabled ? (
          <span id={help} className="sr-only">
            Stickers can be dragged. Focus one, then the arrow keys move it, Shift makes the steps bigger and Alt makes them one pixel. Left and right square brackets (or R and Shift R) turn it, plus and minus
            size it, Page Up and Page Down move it through the stack, Delete removes it and Escape lets go.
          </span>
        ) : null}
        <span role="status" className="sr-only">
          {status}
        </span>
      </div>
    </StickerBoardContext.Provider>
  )
}

type StickerBoardCanvasProps = Omit<PaperProps, "children" | "ref"> & {
  ref?: React.Ref<HTMLElement>
  empty?: React.ReactNode
}

function StickerBoardCanvas({ className, ref, stock = "dot-grid", tilt = false, empty, ...props }: StickerBoardCanvasProps) {
  const board = useStickerBoard()
  useEnsureInkDefs()
  const setRef = useMergedRef<HTMLElement>(board.registerCanvas, ref)
  return (
    <Paper
      data-slot="sticker-board-canvas"
      id={board.canvasId}
      role="group"
      aria-label={board.label}
      aria-describedby={board.editable ? board.help : undefined}
      ref={setRef}
      stock={stock}
      tilt={tilt}
      className={cn("relative min-h-72 w-full min-w-0", className)}
      {...props}
    >
      <div
        data-slot="sticker-board-surface"
        tabIndex={-1}
        className="absolute inset-0 overflow-clip outline-none"
        onPointerDown={(e) => {
          if (e.target === e.currentTarget && board.editable) board.select(null)
        }}
      >
        {board.items.map((it) => (
          <BoardItem key={it.id} item={it} />
        ))}
        {board.items.length === 0 ? (
          <div data-slot="sticker-board-empty" className="pointer-events-none absolute inset-0 grid place-items-center p-6 text-center font-script text-2xl text-pencil-text">
            {empty ?? "Nothing stuck down yet."}
          </div>
        ) : null}
      </div>
    </Paper>
  )
}

interface DragState {
  pointer: number
  mode: "move" | "rotate" | "scale"
  sx: number
  sy: number
  cx: number
  cy: number
  a0: number
  d0: number
  x0: number
  y0: number
  rot0: number
  scale0: number
  x: number
  y: number
  rot: number
  scale: number
  moved: boolean
}

function BoardItem({ item }: { item: StickerBoardItem }) {
  const board = useStickerBoard()
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "")
  const seed = useInkSeed(item.id)
  const face = stickerFace(item.name, board.size, item.id, { idPrefix: `ll-sb${uid}` })
  const selected = board.selectedId === item.id
  const editable = board.editable
  const el = React.useRef<HTMLDivElement | null>(null)
  const art = React.useRef<HTMLSpanElement | null>(null)
  const drag = React.useRef<DragState | null>(null)
  const fw = face?.w ?? 0
  const fh = face?.h ?? 0
  const w = face?.box.w ?? 0
  const h = face?.box.h ?? 0
  const bx = face?.box.x ?? 0
  const by = face?.box.y ?? 0
  const host = useInk({ recipe: stickerBoardItemRecipe, params: { selected, handles: editable }, kind: "frame", seed })
  const name = stickerLabel(item.name)

  const place = (x: number, y: number) => {
    if (el.current) el.current.style.translate = `calc(${x}px - 50%) calc(${y}px - 50%)`
  }
  const turned = (rot: number) => {
    if (!el.current) return
    el.current.style.rotate = `${rot}deg`
    const d = down(rot)
    el.current.style.setProperty("--sb-dx", String(d.dx))
    el.current.style.setProperty("--sb-dy", String(d.dy))
  }
  const sized = (s: number) => {
    if (!el.current) return
    el.current.style.width = `${w * s}px`
    el.current.style.height = `${h * s}px`
    if (art.current) {
      art.current.style.scale = String(s)
      art.current.style.translate = `${-bx * s}px ${-by * s}px`
    }
  }
  const latest = React.useRef(item)
  latest.current = item
  const settle = () => {
    const it = latest.current
    place(it.x, it.y)
    turned(it.rot)
    sized(it.scale)
    if (el.current) el.current.style.zIndex = String(1 + it.z)
  }
  const merged = useMergedRef<HTMLDivElement>(el, host.hostRef)

  const start = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.defaultPrevented || !editable || (e.button ?? 0) !== 0) return
    const handle = (e.target as Element).closest?.("[data-handle]")?.getAttribute("data-handle")
    board.select(item.id)
    const node = e.currentTarget
    const r = node.getBoundingClientRect()
    const cx = r.left + r.width / 2, cy = r.top + r.height / 2
    drag.current = {
      pointer: e.pointerId,
      mode: handle === "rotate" ? "rotate" : handle === "scale" ? "scale" : "move",
      sx: e.clientX,
      sy: e.clientY,
      cx,
      cy,
      a0: Math.atan2(e.clientY - cy, e.clientX - cx),
      d0: Math.max(4, Math.hypot(e.clientX - cx, e.clientY - cy)),
      x0: item.x,
      y0: item.y,
      rot0: item.rot,
      scale0: item.scale,
      x: item.x,
      y: item.y,
      rot: item.rot,
      scale: item.scale,
      moved: false,
    }
    try {
      node.setPointerCapture(e.pointerId)
    } catch {
    }
    node.dataset.dragging = ""
    node.style.zIndex = "1000000"
    node.focus({ preventScroll: true })
  }

  const move = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current
    if (!d || d.pointer !== e.pointerId) return
    const dx = e.clientX - d.sx, dy = e.clientY - d.sy
    if (!d.moved && Math.hypot(dx, dy) < 3) return
    d.moved = true
    if (d.mode === "move") {
      const [x, y] = keepIn(d.x0 + dx, d.y0 + dy, { w, h, rot: d.rot, scale: d.scale }, board.canvas(), board.bounds)
      d.x = x
      d.y = y
      place(x, y)
    } else if (d.mode === "rotate") {
      const a = Math.atan2(e.clientY - d.cy, e.clientX - d.cx)
      let rot = d.rot0 + ((a - d.a0) * 180) / Math.PI
      if (e.shiftKey) rot = Math.round(rot / BIG_TURN) * BIG_TURN
      d.rot = turnTo(rot)
      turned(d.rot)
    } else {
      const dist = Math.hypot(e.clientX - d.cx, e.clientY - d.cy)
      d.scale = clamp(round2(d.scale0 * (dist / d.d0)), board.minScale, board.maxScale)
      sized(d.scale)
    }
  }

  const finish = (cancel: boolean) => (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current
    if (!d || d.pointer !== e.pointerId) return
    drag.current = null
    delete e.currentTarget.dataset.dragging
    e.currentTarget.style.zIndex = String(1 + latest.current.z)
    if (cancel || !d.moved) return settle()
    const change = d.mode === "move" ? { x: Math.round(d.x), y: Math.round(d.y) } : d.mode === "rotate" ? { rot: d.rot } : { scale: d.scale }
    const said = d.mode === "move" ? `${name} moved to ${change.x}, ${change.y}.` : d.mode === "rotate" ? `${name} turned to ${d.rot} degrees.` : `${name} at ${Math.round(d.scale * 100)} percent.`
    board.patch(item.id, change, said)
    setTimeout(settle, 0)
  }

  const keys = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.defaultPrevented || !editable || e.target !== e.currentTarget) return
    const k = e.key
    const cur = latest.current
    if (e.metaKey || (e.ctrlKey && !e.altKey)) {
      if (k.toLowerCase() === "d") {
        e.preventDefault()
        board.duplicate(item.id)
      }
      return
    }
    if (drag.current && k === "Escape") {
      drag.current = null
      delete e.currentTarget.dataset.dragging
      return settle()
    }
    const step = e.altKey ? 1 : e.shiftKey ? BIG_STEP : STEP
    const dx = k === "ArrowRight" ? step : k === "ArrowLeft" ? -step : 0
    const dy = k === "ArrowDown" ? step : k === "ArrowUp" ? -step : 0
    if (dx || dy) {
      e.preventDefault()
      const [x, y] = keepIn(cur.x + dx, cur.y + dy, { w, h, rot: cur.rot, scale: cur.scale }, board.canvas(), board.bounds)
      board.patch(item.id, { x, y }, `${name} at ${x}, ${y}.`)
    } else if (k === "[" || k === "{" || k === "]" || k === "}" || k === "r" || k === "R") {
      e.preventDefault()
      const by = e.shiftKey ? BIG_TURN : TURN
      const left = k === "[" || k === "{" || k === "R"
      board.turn(item.id, left ? -by : by)
    } else if (k === "+" || k === "=" || k === "-" || k === "_") {
      e.preventDefault()
      const f = e.shiftKey ? BIG_ZOOM : ZOOM
      board.resize(item.id, k === "+" || k === "=" ? f : 1 / f)
    } else if (k === "0") {
      e.preventDefault()
      board.patch(item.id, { rot: 0, scale: 1 }, `${name} set upright at full size.`)
    } else if (k === "PageUp" || k === "PageDown") {
      e.preventDefault()
      board.reorder(item.id, k === "PageUp" ? (e.shiftKey ? "front" : "forward") : e.shiftKey ? "back" : "backward")
    } else if (k === "Delete" || k === "Backspace") {
      e.preventDefault()
      const sibling = e.currentTarget.nextElementSibling ?? e.currentTarget.previousElementSibling
      board.remove(item.id)
      const surface = e.currentTarget.parentElement
      ;(sibling instanceof HTMLElement && sibling.dataset.slot === "sticker-board-item" ? sibling : surface)?.focus?.({ preventScroll: true })
    } else if (k === "Escape") {
      e.preventDefault()
      board.select(null)
      e.currentTarget.blur()
    }
  }

  if (!face) return null

  const out = 5
  return (
    <div
      data-slot="sticker-board-item"
      data-id={item.id}
      data-sticker={item.name}
      data-selected={selected ? "" : undefined}
      role="group"
      aria-roledescription="sticker"
      aria-label={name}
      aria-current={selected ? "true" : undefined}
      aria-describedby={editable ? board.help : undefined}
      tabIndex={editable ? 0 : undefined}
      ref={merged}
      {...host.hostProps}
      onPointerDown={start}
      onPointerMove={move}
      onPointerUp={finish(false)}
      onPointerCancel={finish(true)}
      onKeyDown={keys}
      onFocus={(e) => {
        if (e.target === e.currentTarget && editable && !selected) board.select(item.id)
      }}
      className={cn(
        "absolute top-0 left-0 isolate touch-none select-none not-focus-visible:outline-none",
        "[transition:scale_var(--ll-dur-hover)_var(--ll-ease-settle)]",
        editable && "cursor-grab data-dragging:cursor-grabbing hover:scale-[1.03] data-dragging:scale-[1.06] calm:hover:scale-100",
        "[--sb-lift:0] data-dragging:[--sb-lift:1]",
        "forced-colors:data-selected:outline-2 forced-colors:data-selected:outline-[Highlight]"
      )}
      style={{
        width: w * item.scale,
        height: h * item.scale,
        translate: `calc(${item.x}px - 50%) calc(${item.y}px - 50%)`,
        rotate: `${item.rot}deg`,
        zIndex: 1 + item.z,
        "--sb-dx": down(item.rot).dx,
        "--sb-dy": down(item.rot).dy,
        "--ll-drop-sticker": DROP,
      } as React.CSSProperties}
    >
      {host.node}
      <span
        ref={art}
        data-slot="sticker-board-item-art"
        className="pointer-events-none absolute top-0 left-0 origin-top-left"
        style={{ width: fw, height: fh, translate: `${-bx * item.scale}px ${-by * item.scale}px`, scale: item.scale }}
      >
        <svg
          data-ink="sticker"
          aria-hidden="true"
          focusable="false"
          viewBox={`0 0 ${fw} ${fh}`}
          width={fw}
          height={fh}
          className="ll-drop-sticker pointer-events-none block overflow-visible"
          dangerouslySetInnerHTML={{ __html: face.svg }}
        />
      </span>
      {selected && editable ? (
        <>
          <span
            data-handle="rotate"
            aria-hidden="true"
            className="absolute cursor-grab"
            style={{ left: "50%", top: -(out + HANDLE.rotateUp), width: HANDLE.hit, height: HANDLE.hit, translate: "-50% -50%" }}
          />
          <span
            data-handle="scale"
            aria-hidden="true"
            className="absolute cursor-nwse-resize"
            style={{ left: `calc(100% + ${out + HANDLE.scaleOut - HANDLE.scaleSize / 2}px)`, top: `calc(100% + ${out + HANDLE.scaleOut - HANDLE.scaleSize / 2}px)`, width: HANDLE.hit, height: HANDLE.hit, translate: "-50% -50%" }}
          />
        </>
      ) : null}
    </div>
  )
}

type ToolbarAction = "turn" | "size" | "layer" | "duplicate" | "delete" | "export"

type StickerBoardToolbarProps = Omit<React.ComponentProps<"div">, "children"> & {
  actions?: readonly ToolbarAction[]
}

const ALL_ACTIONS: readonly ToolbarAction[] = ["turn", "size", "layer", "duplicate", "delete", "export"]

function StickerBoardToolbar({ className, actions = ALL_ACTIONS, onKeyDown, ...props }: StickerBoardToolbarProps) {
  const board = useStickerBoard()
  const id = board.selectedId
  const off = !id || !board.editable
  const row = React.useRef<HTMLElement | null>(null)
  const item = board.items.find((s) => s.id === id)

  const roving = (e: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(e)
    if (e.defaultPrevented) return
    const k = e.key
    if (k !== "ArrowRight" && k !== "ArrowLeft" && k !== "Home" && k !== "End") return
    const list = [...(row.current?.querySelectorAll<HTMLButtonElement>("button:not(:disabled)") ?? [])]
    const at = list.indexOf(document.activeElement as HTMLButtonElement)
    if (at < 0) return
    e.preventDefault()
    const rtl = getComputedStyle(row.current as Element).direction === "rtl"
    const dir = (k === "ArrowRight" ? 1 : -1) * (rtl ? -1 : 1)
    const to = k === "Home" ? 0 : k === "End" ? list.length - 1 : (at + dir + list.length) % list.length
    list[to].focus()
  }

  const removeAndMoveOn = (gone: string) => {
    const surface = document.getElementById(board.canvasId)?.querySelector<HTMLElement>('[data-slot="sticker-board-surface"]')
    board.remove(gone)
    surface?.focus({ preventScroll: true })
  }

  const tool = (label: string, icon: string, run: () => void, o: { text?: string; disabled?: boolean; always?: boolean; mirror?: boolean } = {}) => (
    <Button
      key={label}
      type="button"
      variant="outline"
      size={o.text ? "sm" : "icon-sm"}
      aria-label={label}
      title={label}
      disabled={o.always ? false : (o.disabled ?? off)}
      onClick={run}
      data-tool={label}
    >
      {icon ? <Icon name={icon} size={16} className={o.mirror ? "-scale-x-100" : undefined} /> : null}
      {o.text}
    </Button>
  )
  const has = (a: ToolbarAction) => actions.includes(a)
  const groups: React.ReactNode[] = []
  const group = (key: string, children: React.ReactNode) =>
    groups.push(
      <div key={key} role="presentation" className="flex items-center gap-1.5">
        {children}
      </div>
    )
  if (has("turn")) group("turn", [tool("Turn left", "rotate-cw", () => id && board.turn(id, -TURN), { mirror: true }), tool("Turn right", "rotate-cw", () => id && board.turn(id, TURN))])
  if (has("size"))
    group("size", [
      tool("Smaller", "minus", () => id && board.resize(id, 1 / ZOOM), { disabled: off || (item ? item.scale <= board.minScale : false) }),
      tool("Larger", "plus", () => id && board.resize(id, ZOOM), { disabled: off || (item ? item.scale >= board.maxScale : false) }),
    ])
  if (has("layer"))
    group("layer", [
      tool("Send to back", "", () => id && board.reorder(id, "back"), { text: "Back" }),
      tool("Send backward", "arrow-down", () => id && board.reorder(id, "backward")),
      tool("Bring forward", "arrow-up", () => id && board.reorder(id, "forward")),
      tool("Bring to front", "", () => id && board.reorder(id, "front"), { text: "Front" }),
    ])
  if (has("duplicate") || has("delete"))
    group("edit", [
      has("duplicate") && tool("Duplicate", "copy", () => id && board.duplicate(id)),
      has("delete") && tool("Delete", "trash", () => id && removeAndMoveOn(id)),
    ])
  if (has("export")) group("export", [tool("Export", "download", board.exportBoard, { text: "Export", always: true })])

  return (
    <Paper
      data-slot="sticker-board-toolbar"
      role="toolbar"
      aria-label="Sticker tools"
      aria-controls={board.canvasId}
      ref={row}
      onKeyDown={roving}
      stock="slip"
      edge="cut"
      tilt={false}
      shadow="hair"
      className={cn("flex flex-wrap items-center gap-x-4 gap-y-2 px-2 py-1.5", className)}
      {...props}
    >
      {groups}
    </Paper>
  )
}

export { StickerBoard, StickerBoardCanvas, StickerBoardToolbar, useStickerBoard, addSticker, reorderSticker, boardPoint }
export type { StickerBoardItem, StickerBoardProps, StickerBoardCanvasProps, StickerBoardToolbarProps, StickerBoardExport, BoundsMode as StickerBoardBounds }

"use client"

import * as React from "react"

import { Icon } from "@/components/ui/icon"
import { Input } from "@/components/ui/input"
import { Mascot } from "@/components/ui/mascot"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { useEnsureInkDefs } from "@/lib/ink/react"
import { categoryLabel, hasSticker, stickerCatalog, stickerFace, stickerLabel, type StickerCatalogEntry } from "@/lib/ink/recipes/sticker-ink"
import { cn } from "@/lib/utils"

type StickerPickerItem = StickerCatalogEntry

type StickerPickerInput = string | { name: string; label?: string; category?: string; tags?: readonly string[] }

function catalogFrom(list?: readonly StickerPickerInput[]): StickerPickerItem[] {
  const all = stickerCatalog()
  if (!list) return all
  const known = new Map(all.map((e) => [e.name, e]))
  return list.flatMap((entry) => {
    const name = typeof entry === "string" ? entry : entry.name
    const base = known.get(name) ?? (hasSticker(name) ? { name, label: stickerLabel(name), category: "stickers", categoryLabel: "Stickers", tags: [] } : null)
    if (!base) return []
    if (typeof entry === "string") return [base]
    const category = entry.category ?? base.category
    return [{ ...base, label: entry.label ?? base.label, category, categoryLabel: entry.category ? categoryLabel(entry.category) : base.categoryLabel, tags: [...base.tags, ...(entry.tags ?? [])] }]
  })
}

interface StickerPickerContextValue {
  catalog: readonly StickerPickerItem[]
  recent: readonly string[]
  value: string | null | undefined
  choose(item: StickerPickerItem): void
  uid: string
}

const StickerPickerContext = React.createContext<StickerPickerContextValue | null>(null)

function useStickerPicker(): StickerPickerContextValue {
  const ctx = React.useContext(StickerPickerContext)
  if (!ctx) throw new Error("Sticker picker parts must be used inside <StickerPicker>")
  return ctx
}

type StickerPickerProps = React.ComponentProps<typeof Popover> & {
  onSelect?: (sticker: StickerPickerItem) => void
  value?: string | null
  stickers?: readonly StickerPickerInput[]
  recent?: readonly string[]
  closeOnSelect?: boolean
}

const NO_RECENT: readonly string[] = []

function StickerPicker({ open: openProp, defaultOpen = false, onOpenChange, onSelect, value, stickers, recent = NO_RECENT, closeOnSelect = true, children, ...props }: StickerPickerProps) {
  const [inner, setInner] = React.useState(defaultOpen)
  const open = openProp ?? inner
  const setOpen = React.useCallback(
    (next: boolean) => {
      if (openProp === undefined) setInner(next)
      onOpenChange?.(next)
    },
    [openProp, onOpenChange]
  )
  const catalog = React.useMemo(() => catalogFrom(stickers), [stickers])
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "")
  const ctx = React.useMemo<StickerPickerContextValue>(
    () => ({
      catalog,
      recent,
      value,
      uid,
      choose(item) {
        onSelect?.(item)
        if (closeOnSelect) setOpen(false)
      },
    }),
    [catalog, recent, value, uid, onSelect, closeOnSelect, setOpen]
  )
  return (
    <StickerPickerContext.Provider value={ctx}>
      <Popover data-slot="sticker-picker" open={open} onOpenChange={setOpen} {...props}>
        {children}
      </Popover>
    </StickerPickerContext.Provider>
  )
}

function StickerPickerTrigger({ ...props }: React.ComponentProps<typeof PopoverTrigger>) {
  return <PopoverTrigger data-slot="sticker-picker-trigger" {...props} />
}

interface Section {
  key: string
  label: string
  items: readonly StickerPickerItem[]
}

const matches = (e: StickerPickerItem, words: readonly string[]): boolean => {
  const hay = `${e.label} ${e.name} ${e.categoryLabel} ${e.tags.join(" ")}`.toLowerCase()
  return words.every((w) => hay.includes(w))
}

function neighbour(sections: readonly Section[], at: { s: number; i: number }, key: string, cols: number): { s: number; i: number } | null {
  const last = sections.length - 1
  if (key === "ArrowRight") return at.i < sections[at.s].items.length - 1 ? { s: at.s, i: at.i + 1 } : at.s < last ? { s: at.s + 1, i: 0 } : null
  if (key === "ArrowLeft") return at.i > 0 ? { s: at.s, i: at.i - 1 } : at.s > 0 ? { s: at.s - 1, i: sections[at.s - 1].items.length - 1 } : null
  const col = at.i % cols
  if (key === "ArrowDown") {
    if (at.i + cols < sections[at.s].items.length) return { s: at.s, i: at.i + cols }
    return at.s < last ? { s: at.s + 1, i: Math.min(col, sections[at.s + 1].items.length - 1) } : null
  }
  if (key === "ArrowUp") {
    if (at.i - cols >= 0) return { s: at.s, i: at.i - cols }
    if (at.s === 0) return null
    const prev = sections[at.s - 1].items.length
    const lastRow = Math.floor((prev - 1) / cols) * cols
    return { s: at.s - 1, i: Math.min(lastRow + col, prev - 1) }
  }
  return null
}

type StickerPickerContentProps = Omit<React.ComponentProps<typeof PopoverContent>, "children"> & {
  columns?: number
  size?: number
  placeholder?: string
}

function StickerPickerContent({ className, columns = 5, size = 44, placeholder = "Search stickers", ...props }: StickerPickerContentProps) {
  useStickerPicker()
  const perRow = Math.max(1, Math.floor(columns) || 1)
  return (
    <PopoverContent
      data-slot="sticker-picker-content"
      aria-label="Stickers"
      align="start"
      className={cn("w-[min(23rem,calc(100vw-2rem))] p-3", className)}
      {...props}
    >
      <PickerBody columns={perRow} size={size} placeholder={placeholder} />
    </PopoverContent>
  )
}

function PickerBody({ columns, size, placeholder }: { columns: number; size: number; placeholder: string }) {
  const picker = useStickerPicker()
  useEnsureInkDefs()
  const [query, setQuery] = React.useState("")
  const [category, setCategory] = React.useState("all")
  const [activeKey, setActiveKey] = React.useState<string | null>(null)
  const input = React.useRef<HTMLInputElement | null>(null)
  const list = React.useRef<HTMLDivElement | null>(null)
  const listId = `sp-list-${picker.uid}`

  const words = query.trim().toLowerCase().split(/\s+/).filter(Boolean)
  const categories = React.useMemo(() => {
    const seen = new Map<string, string>()
    for (const e of picker.catalog) if (!seen.has(e.category)) seen.set(e.category, e.categoryLabel)
    return [...seen]
  }, [picker.catalog])

  const everything = React.useMemo<Section[]>(() => {
    const byName = new Map(picker.catalog.map((e) => [e.name, e]))
    const found = picker.catalog.filter((e) => (category === "all" || e.category === category) && matches(e, words))
    if (words.length || category !== "all") return found.length ? [{ key: "found", label: words.length ? `${found.length} found` : (categories.find(([k]) => k === category)?.[1] ?? ""), items: found }] : []
    const out: Section[] = []
    const recent = picker.recent.map((n) => byName.get(n)).filter((e): e is StickerPickerItem => !!e)
    if (recent.length) out.push({ key: "recent", label: "Recent", items: recent })
    for (const [key, label] of categories) out.push({ key, label, items: picker.catalog.filter((e) => e.category === key) })
    return out
  }, [picker.catalog, picker.recent, category, categories, query])

  const progressive = words.length === 0 && category === "all"
  const [shown, setShown] = React.useState(2)
  React.useEffect(() => {
    if (!progressive || shown >= everything.length) return
    const t = setTimeout(() => setShown((n) => n + 1), 24)
    return () => clearTimeout(t)
  }, [progressive, shown, everything.length])
  const sections = progressive ? everything.slice(0, shown) : everything
  const total = everything.reduce((n, s) => n + s.items.length, 0)

  const keyOf = (s: Section, e: StickerPickerItem) => `${s.key}:${e.name}`
  const flat = sections.flatMap((s, si) => s.items.map((e, i) => ({ s: si, i, e, key: keyOf(s, e) })))
  const current = flat.find((f) => f.key === activeKey) ?? flat[0] ?? null
  const optionId = (key: string) => `${listId}-${key.replace(/[^a-zA-Z0-9-]/g, "_")}`

  React.useEffect(() => {
    if (!current) return
    document.getElementById(optionId(current.key))?.scrollIntoView?.({ block: "nearest" })
  }, [current?.key])

  const goTo = (target: { s: number; i: number } | null) => {
    if (!target) return
    const f = flat.find((x) => x.s === target.s && x.i === target.i)
    if (f) setActiveKey(f.key)
  }

  const keys = (e: React.KeyboardEvent<HTMLInputElement>) => {
    const el = e.currentTarget
    const k = e.key
    if (k === "Enter") {
      if (current && !e.nativeEvent.isComposing) {
        e.preventDefault()
        picker.choose(current.e)
      }
      return
    }
    if (!current) return
    const at = { s: current.s, i: current.i }
    if (k === "ArrowUp" || k === "ArrowDown") {
      e.preventDefault()
      goTo(neighbour(sections, at, k, columns))
    } else if (k === "ArrowLeft" || k === "ArrowRight") {
      const rtl = getComputedStyle(el).direction === "rtl"
      const forward = (k === "ArrowRight") !== rtl
      const caretFree = el.value === "" || (forward ? el.selectionStart === el.value.length : el.selectionEnd === 0)
      if (!caretFree) return
      e.preventDefault()
      goTo(neighbour(sections, at, forward ? "ArrowRight" : "ArrowLeft", columns))
    } else if ((k === "Home" || k === "End") && el.value === "") {
      e.preventDefault()
      const f = k === "Home" ? flat[0] : flat[flat.length - 1]
      if (f) setActiveKey(f.key)
    }
  }

  const count = flat.length
  return (
    <>
      <Input
        ref={input}
        type="text"
        role="combobox"
        aria-label="Search stickers"
        aria-expanded={count > 0}
        aria-controls={listId}
        aria-autocomplete="list"
        aria-activedescendant={current ? optionId(current.key) : undefined}
        autoComplete="off"
        spellCheck={false}
        placeholder={placeholder}
        value={query}
        onChange={(e) => {
          setQuery(e.target.value)
          setActiveKey(null)
        }}
        onKeyDown={keys}
        className="w-full"
      />
      {categories.length > 1 ? (
        <div data-slot="sticker-picker-categories" role="group" aria-label="Categories" className="-mx-1 mt-2 flex gap-1 overflow-x-auto px-1 pb-1 [mask-image:linear-gradient(to_right,black_calc(100%-28px),transparent)] rtl:[mask-image:linear-gradient(to_left,black_calc(100%-28px),transparent)]">
          {[["all", "All"] as const, ...categories].map(([key, label]) => (
            <button
              key={key}
              type="button"
              aria-pressed={category === key}
              onClick={() => {
                setCategory(key)
                setActiveKey(null)
                input.current?.focus()
              }}
              className={cn(
                "inline-flex min-h-6 shrink-0 items-center px-2 font-hand text-sm font-bold whitespace-nowrap text-muted-foreground transition-colors duration-(--ll-dur-hover)",
                "hover:text-foreground aria-pressed:ll-swipe aria-pressed:text-foreground focus-visible:ll-swipe forced-colors:aria-pressed:underline"
              )}
            >
              {label}
            </button>
          ))}
        </div>
      ) : null}
      <div
        ref={list}
        id={listId}
        role="listbox"
        aria-label="Stickers"
        data-slot="sticker-picker-list"
        hidden={count === 0}
        className="mt-2 max-h-64 min-h-24 overflow-y-auto overscroll-contain pe-1"
      >
        {sections.map((s) => (
          <div key={s.key} role="group" aria-labelledby={`${listId}-h-${s.key}`} className="mb-1.5 last:mb-0">
            <div id={`${listId}-h-${s.key}`} aria-hidden="true" className="px-1 pt-1 pb-0.5 font-script text-lg leading-none text-muted-foreground">
              {s.label}
            </div>
            <div className="grid gap-0.5" style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}>
              {s.items.map((e) => {
                const key = keyOf(s, e)
                return <Option key={key} entry={e} id={optionId(key)} active={current?.key === key} selected={picker.value === e.name} size={size} scope={`${picker.uid}${s.key}`} onActivate={() => setActiveKey(key)} onChoose={() => picker.choose(e)} />
              })}
            </div>
          </div>
        ))}
      </div>
      {count === 0 ? (
        <div data-slot="sticker-picker-empty" className="mt-2 grid min-h-24 place-items-center gap-1 px-2 py-5 text-center">
          <Mascot pose="search" size={64} />
          <p className="font-script text-xl leading-tight text-muted-foreground">{query.trim() ? <>Nothing looks like &ldquo;{query.trim()}&rdquo;.</> : "No stickers to choose from."}</p>
        </div>
      ) : null}
      <div className="mt-2 flex min-h-6 items-baseline justify-between gap-2 border-t border-dashed border-pencil-mark/60 pt-1.5" aria-hidden="true">
        <span className="truncate font-script text-xl leading-none text-foreground">{current?.e.label ?? ""}</span>
        <span className="shrink-0 text-xs text-muted-foreground">{current ? current.e.categoryLabel : ""}</span>
      </div>
      <span role="status" className="sr-only">
        {total === 0 ? "No stickers found." : `${total} ${total === 1 ? "sticker" : "stickers"}.`}
      </span>
    </>
  )
}

interface OptionProps {
  entry: StickerPickerItem
  id: string
  active: boolean
  selected: boolean
  size: number
  scope: string
  onActivate(): void
  onChoose(): void
}

function Option({ entry, id, active, selected, size, scope, onActivate, onChoose }: OptionProps) {
  const face = stickerFace(entry.name, size, entry.name, { peel: active ? true : undefined, idPrefix: `ll-sp${scope}${entry.name}`.replace(/[^a-zA-Z0-9-]/g, "") })
  if (!face) return null
  const cell = size + 12
  return (
    <div
      id={id}
      role="option"
      aria-selected={selected}
      aria-label={entry.label}
      data-slot="sticker-picker-option"
      data-active={active ? "" : undefined}
      data-selected={selected ? "" : undefined}
      onPointerMove={() => !active && onActivate()}
      onMouseDown={(e) => e.preventDefault()}
      onClick={onChoose}
      className="group/option relative flex cursor-pointer items-center justify-center data-active:ll-swipe"
      style={{ height: cell }}
    >
      <svg
        data-ink="sticker"
        aria-hidden="true"
        focusable="false"
        viewBox={`0 0 ${face.w} ${face.h}`}
        width={face.w}
        height={face.h}
        className="pointer-events-none block overflow-visible transition-[scale,rotate] duration-(--ll-dur-hover) ease-(--ll-ease-settle) group-data-active/option:-rotate-3 group-data-active/option:scale-110 group-data-active/option:ll-drop-sticker"
        dangerouslySetInnerHTML={{ __html: face.svg }}
      />
      {selected ? <Icon name="check" size={14} className="pointer-events-none absolute end-0.5 top-0.5 text-foreground" /> : null}
    </div>
  )
}

export { StickerPicker, StickerPickerTrigger, StickerPickerContent, useStickerPicker }
export type { StickerPickerProps, StickerPickerContentProps, StickerPickerItem, StickerPickerInput }

"use client"

import * as React from "react"

import { Paper, type PaperProps } from "@/components/ui/paper"
import { useEnsureInkDefs, useInk, useInkSeed } from "@/lib/ink/react"
import { hasSticker, kissCut, stickerFace, stickerLabel } from "@/lib/ink/recipes/sticker-ink"
import { stickerSheetRecipe, stickerSlotRecipe } from "@/lib/ink/recipes/sticker-sheet-ink"
import { cn } from "@/lib/utils"

interface StickerSheetPeel {
  id: string
  name: string
  label: string
  dragged: boolean
  x?: number
  y?: number
}

interface StickerSheetContextValue {
  peeled: readonly string[]
  peel(item: StickerSheetPeel): void
  stick(item: StickerSheetPeel): void
  size: number
  restorable: boolean
  disabled: boolean
  uid: string
}

const StickerSheetContext = React.createContext<StickerSheetContextValue | null>(null)

function useStickerSheet(): StickerSheetContextValue {
  const ctx = React.useContext(StickerSheetContext)
  if (!ctx) throw new Error("StickerSheetItem must be used inside <StickerSheet>")
  return ctx
}

const cellOf = (size: number) => Math.round(size + 22)

const BACKINGS = {
  glassine: { stock: "slip", tint: "color-mix(in srgb, var(--ll-sky) 13%, var(--ll-paper))" },
  kraft: { stock: "kraft", tint: undefined },
  paper: { stock: "paper", tint: undefined },
} as const satisfies Record<string, { stock: PaperProps["stock"]; tint: string | undefined }>

type StickerSheetProps = Omit<PaperProps, "ref" | "children" | "stock" | "onChange" | "size"> & {
  ref?: React.Ref<HTMLElement>
  stickers?: readonly string[]
  children?: React.ReactNode
  columns?: number
  size?: number
  title?: string
  backing?: keyof typeof BACKINGS
  peeled?: readonly string[]
  defaultPeeled?: readonly string[]
  onPeeledChange?: (peeled: string[]) => void
  onPeel?: (item: StickerSheetPeel) => void
  onStick?: (item: StickerSheetPeel) => void
  restorable?: boolean
  disabled?: boolean
  label?: string
}

function StickerSheet({
  className,
  children,
  ref,
  stickers,
  columns = 4,
  size = 72,
  title,
  backing = "glassine",
  peeled: peeledProp,
  defaultPeeled = [],
  onPeeledChange,
  onPeel,
  onStick,
  restorable = true,
  disabled = false,
  label = "Sticker sheet",
  tilt = true,
  seed: seedProp,
  style,
  ...props
}: StickerSheetProps) {
  const seed = useInkSeed(seedProp)
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "")
  const titleId = React.useId()
  const [inner, setInner] = React.useState<readonly string[]>(defaultPeeled)
  const controlled = peeledProp !== undefined
  const peeled = controlled ? peeledProp : inner
  const [status, setStatus] = React.useState("")
  const latest = React.useRef(peeled)
  latest.current = peeled

  const change = React.useCallback(
    (next: string[]) => {
      latest.current = next
      if (!controlled) setInner(next)
      onPeeledChange?.(next)
    },
    [controlled, onPeeledChange]
  )
  const ctx = React.useMemo<StickerSheetContextValue>(
    () => ({
      peeled,
      size,
      restorable,
      disabled,
      uid,
      peel(item) {
        if (latest.current.includes(item.id)) return
        change([...latest.current, item.id])
        onPeel?.(item)
        setStatus(`${item.label} peeled off.`)
      },
      stick(item) {
        if (!latest.current.includes(item.id)) return
        change(latest.current.filter((id) => id !== item.id))
        onStick?.(item)
        setStatus(`${item.label} stuck back on.`)
      },
    }),
    [peeled, size, restorable, disabled, uid, change, onPeel, onStick]
  )

  const cell = cellOf(size)
  const B = BACKINGS[backing]
  const header = title ? 34 : 0
  const print = useInk({ recipe: stickerSheetRecipe, params: { top: header }, kind: "print", seed: `${seed}|print` })
  const items = React.Children.count(children) ? children : (stickers ?? []).map((n) => <StickerSheetItem key={n} name={n} />)
  const here = new Set<string>()
  let unknown = 0
  React.Children.toArray(items).forEach((child) => {
    const p = React.isValidElement(child) ? (child.props as { name?: unknown; id?: unknown }) : null
    if (p && typeof p.name === "string") {
      if (hasSticker(p.name)) here.add(typeof p.id === "string" ? p.id : p.name)
    } else unknown++
  })
  const left = here.size + unknown - [...here].filter((id) => peeled.includes(id)).length

  return (
    <StickerSheetContext.Provider value={ctx}>
      <Paper
        data-slot="sticker-sheet"
        data-backing={backing}
        data-disabled={disabled ? "" : undefined}
        role="group"
        aria-labelledby={title ? titleId : undefined}
        aria-label={title ? undefined : label}
        ref={ref}
        stock={B.stock}
        tilt={tilt}
        seed={seed}
        className={cn("w-fit max-w-full p-4 pt-4 has-[[data-dragging]]:z-(--ll-z-raised)", disabled && "opacity-70", className)}
        style={{ ...(B.tint ? { "--ll-stock": B.tint } : null), ...style } as React.CSSProperties}
        {...props}
      >
        <div ref={print.hostRef} {...print.hostProps} data-slot="sticker-sheet-print" aria-hidden="true" className="pointer-events-none absolute inset-1.5 isolate">
          {print.node}
        </div>
        {backing === "glassine" ? (
          <span
            aria-hidden="true"
            data-slot="sticker-sheet-sheen"
            className="pointer-events-none absolute inset-0 [background:linear-gradient(112deg,transparent_30%,color-mix(in_srgb,var(--ll-photo)_42%,transparent)_43%,transparent_56%)] calm:hidden"
          />
        ) : null}
        {title ? (
          <div className="relative mb-2 flex h-6 items-baseline justify-between gap-3 px-1.5">
            <p id={titleId} className="truncate font-type text-sm text-pencil-text">
              {title}
            </p>
            <p className="shrink-0 font-type text-xs text-pencil-text ll-num">{Math.max(0, left)} left</p>
          </div>
        ) : null}
        <div data-slot="sticker-sheet-grid" className="relative grid justify-center gap-1 p-2" style={{ gridTemplateColumns: `repeat(${Math.max(1, columns)}, ${cell}px)` }}>
          {items}
        </div>
        <span role="status" className="sr-only">
          {status}
        </span>
      </Paper>
    </StickerSheetContext.Provider>
  )
}

type StickerSheetItemProps = Omit<React.ComponentProps<"button">, "name" | "id" | "onPointerDown" | "onPointerMove" | "onPointerUp" | "onPointerCancel"> & {
  name: string
  id?: string
  label?: string
  size?: number
}

const DRAG_AT = 6
const DRAG_OFF = 18

function StickerSheetItem({ name, id: idProp, label: labelProp, size: sizeProp, className, onClick, disabled: disabledProp, ...props }: StickerSheetItemProps) {
  const sheet = useStickerSheet()
  useEnsureInkDefs()
  const id = idProp ?? name
  const px = sizeProp ?? sheet.size
  const cell = cellOf(px)
  const label = labelProp ?? stickerLabel(name)
  const peeled = sheet.peeled.includes(id)
  const prefix = `ll-ss${sheet.uid}${id}`.replace(/[^a-zA-Z0-9-]/g, "")
  const face = stickerFace(name, px, id, { idPrefix: prefix })
  const [warm, setWarm] = React.useState(false)
  const flap = warm ? stickerFace(name, px, id, { peel: true, idPrefix: `${prefix}p` }) : null
  const slot = useInk({ recipe: stickerSlotRecipe, params: {}, kind: "frame", seed: `${prefix}` })
  const drag = React.useRef<{ pointer: number; sx: number; sy: number; started: boolean } | null>(null)
  const held = React.useRef<HTMLSpanElement | null>(null)
  const slotEl = React.useRef<HTMLDivElement | null>(null)
  const suppress = React.useRef(false)
  const peeledNow = React.useRef(peeled)
  peeledNow.current = peeled
  const disabled = disabledProp || sheet.disabled
  const spent = peeled && !sheet.restorable
  const item = (dragged: boolean, e?: { clientX: number; clientY: number }): StickerSheetPeel => ({ id, name, label, dragged, x: e?.clientX, y: e?.clientY })

  const carry = (dx: number, dy: number) => {
    if (!held.current) return
    held.current.style.translate = `${dx}px ${dy}px`
    held.current.style.rotate = `${Math.max(-14, Math.min(14, dx * 0.06))}deg`
  }
  const putDown = () => {
    if (!held.current) return
    held.current.style.translate = ""
    held.current.style.rotate = ""
  }
  React.useEffect(() => {
    if (peeled) return
    slotEl.current?.removeAttribute("data-drop")
    putDown()
  }, [peeled])

  if (!face) return null
  const cx = face.box.x + face.box.w / 2
  const cy = face.box.y + face.box.h / 2
  const at = { left: cell / 2 - cx, top: cell / 2 - cy }
  const kiss = kissCut(face, `${prefix}k`)

  const down = (e: React.PointerEvent<HTMLButtonElement>) => {
    setWarm(true)
    if (disabled || peeled || e.pointerType === "touch" || (e.button ?? 0) !== 0) return
    suppress.current = false
    drag.current = { pointer: e.pointerId, sx: e.clientX, sy: e.clientY, started: false }
    try {
      e.currentTarget.setPointerCapture(e.pointerId)
    } catch {
    }
  }
  const move = (e: React.PointerEvent<HTMLButtonElement>) => {
    const d = drag.current
    if (!d || d.pointer !== e.pointerId) return
    const dx = e.clientX - d.sx, dy = e.clientY - d.sy
    if (!d.started && Math.hypot(dx, dy) < DRAG_AT) return
    if (!d.started) {
      d.started = true
      slotEl.current?.setAttribute("data-dragging", "")
    }
    carry(dx, dy)
  }
  const up = (cancel: boolean) => (e: React.PointerEvent<HTMLButtonElement>) => {
    const d = drag.current
    if (!d || d.pointer !== e.pointerId) return
    drag.current = null
    if (!d.started) return
    slotEl.current?.removeAttribute("data-dragging")
    suppress.current = !cancel
    setTimeout(() => (suppress.current = false), 0)
    const far = Math.hypot(e.clientX - d.sx, e.clientY - d.sy) >= DRAG_OFF
    if (cancel || !far) return putDown()
    slotEl.current?.setAttribute("data-drop", "")
    sheet.peel(item(true, e))
    setTimeout(() => {
      if (peeledNow.current) return
      slotEl.current?.removeAttribute("data-drop")
      putDown()
    }, 0)
  }

  return (
    <div ref={slotEl} data-slot="sticker-sheet-slot" data-state={peeled ? "peeled" : "stuck"} className="group/slot relative shrink-0" style={{ width: cell, height: cell }}>
      <svg
        data-ink="prop"
        aria-hidden="true"
        focusable="false"
        viewBox={`0 0 ${face.w} ${face.h}`}
        width={face.w}
        height={face.h}
        className="pointer-events-none absolute block overflow-visible"
        style={at}
        dangerouslySetInnerHTML={{ __html: kiss }}
      />
      <button
        type="button"
        data-slot="sticker-sheet-item"
        data-sticker={name}
        aria-label={peeled ? (sheet.restorable ? `Put ${label} sticker back` : `${label} sticker, peeled`) : `Peel ${label} sticker`}
        aria-disabled={spent ? true : undefined}
        disabled={disabled}
        ref={slot.hostRef}
        {...slot.hostProps}
        onPointerEnter={() => setWarm(true)}
        onFocus={() => setWarm(true)}
        onPointerDown={down}
        onPointerMove={move}
        onPointerUp={up(false)}
        onPointerCancel={up(true)}
        onClick={(e) => {
          onClick?.(e)
          if (e.defaultPrevented || spent) return
          if (suppress.current) {
            suppress.current = false
            return
          }
          if (peeled) sheet.stick(item(false))
          else sheet.peel(item(false))
        }}
        className={cn(
          "absolute inset-0 touch-manipulation select-none not-focus-visible:outline-none",
          "enabled:cursor-grab enabled:active:cursor-grabbing disabled:cursor-default aria-disabled:cursor-default!",
          "group-data-[dragging]/slot:z-(--ll-z-raised)",
          className
        )}
        {...props}
      >
        {slot.node}
        <span
          data-slot="sticker-sheet-art"
          className={cn(
            "pointer-events-none absolute block transition-[translate,rotate,scale,opacity] duration-(--ll-dur-sheet) ease-(--ll-ease-settle)",
            "group-data-[state=peeled]/slot:translate-x-4 group-data-[state=peeled]/slot:-translate-y-6 group-data-[state=peeled]/slot:-rotate-12 group-data-[state=peeled]/slot:scale-110 group-data-[state=peeled]/slot:opacity-0",
            "group-data-[drop]/slot:translate-x-0! group-data-[drop]/slot:translate-y-0! group-data-[drop]/slot:rotate-0! group-data-[drop]/slot:scale-100! group-data-[drop]/slot:duration-(--ll-dur-fade)!"
          )}
          style={{ ...at, width: face.w, height: face.h }}
          onTransitionEnd={(e) => {
            if (e.target !== e.currentTarget || e.propertyName !== "opacity" || !peeled || !slotEl.current?.hasAttribute("data-drop")) return
            slotEl.current.removeAttribute("data-drop")
            putDown()
          }}
        >
          <span
            ref={held}
            className="relative block size-full transition-[scale,rotate] duration-(--ll-dur-hover) ease-(--ll-ease-settle) group-hover/slot:-rotate-2 group-hover/slot:scale-[1.04] group-data-[dragging]/slot:scale-110 group-data-[dragging]/slot:transition-none"
          >
            <svg
              data-ink="sticker"
              aria-hidden="true"
              focusable="false"
              viewBox={`0 0 ${face.w} ${face.h}`}
              width={face.w}
              height={face.h}
              className="ll-drop-sticker pointer-events-none absolute inset-0 block overflow-visible transition-opacity duration-(--ll-dur-fade) group-hover/slot:opacity-0 group-has-[:focus-visible]/slot:opacity-0 group-data-[dragging]/slot:opacity-0 group-data-[state=peeled]/slot:opacity-0"
              dangerouslySetInnerHTML={{ __html: face.svg }}
            />
            {flap ? (
              <svg
                data-ink="sticker"
                aria-hidden="true"
                focusable="false"
                viewBox={`0 0 ${flap.w} ${flap.h}`}
                width={flap.w}
                height={flap.h}
                className="ll-drop-sticker pointer-events-none absolute inset-0 block overflow-visible opacity-0 transition-opacity duration-(--ll-dur-fade) group-hover/slot:opacity-100 group-has-[:focus-visible]/slot:opacity-100 group-data-[dragging]/slot:opacity-100 group-data-[state=peeled]/slot:opacity-100"
                dangerouslySetInnerHTML={{ __html: flap.svg }}
              />
            ) : null}
          </span>
        </span>
      </button>
    </div>
  )
}

export { StickerSheet, StickerSheetItem, useStickerSheet }
